:root{
  --gold:#ffd479; --gold-deep:#c9963c; --gold-pale:#fff3cd;
  --teal:#63e3d1; --teal-deep:#1c7f7a;
  --ink:#0b1420; --ink2:#111f2e; --panel:rgba(9,18,28,.82);
  --text:#f7f2e7; --muted:#a9bcc4;
  --rose:#ff8a8a; --violet:#b490ff; --ember:#ff9e57;
  --hud-h: 96px;
  --font-display: "Palatino Linotype","Book Antiqua",Palatino,Georgia,serif;
  --font-ui: "Avenir Next","Segoe UI",system-ui,-apple-system,sans-serif;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;overflow:hidden;background:#070d14;color:var(--text);
  font-family:var(--font-ui);-webkit-font-smoothing:antialiased;user-select:none}
#app{position:fixed;inset:0;overflow:hidden}
#viewport{position:absolute;inset:0}
#viewport canvas{display:block;width:100%;height:100%;touch-action:none;filter:saturate(1.14) contrast(1.04)}
#grade{position:absolute;inset:0;pointer-events:none;z-index:2;
  background:linear-gradient(180deg,rgba(13,28,54,.14) 0%,transparent 30%,transparent 72%,rgba(8,14,24,.38) 100%);
  mix-blend-mode:multiply}
#vignette{position:absolute;inset:0;pointer-events:none;z-index:3;
  background:radial-gradient(ellipse at 50% 46%,transparent 52%,rgba(5,9,16,.52) 100%)}
#flash{position:absolute;inset:0;pointer-events:none;z-index:40;background:#fff;opacity:0;transition:opacity .2s}
#hud{position:absolute;inset:0;pointer-events:none;z-index:20;font-family:var(--font-ui)}
#hud button,#hud .interactive{pointer-events:auto}
.hidden{display:none !important}

/* ============ vitals ============ */
#vit{position:absolute;left:18px;top:16px;display:flex;gap:10px;align-items:center;filter:drop-shadow(0 4px 12px rgba(0,0,0,.6))}
.portrait-wrap{width:78px;height:78px;position:relative;flex:0 0 auto}
#portrait{width:100%;height:100%;border-radius:50%;background:#16283a;display:block;
  box-shadow:0 0 0 2px var(--gold-deep),0 0 0 5px rgba(9,18,28,.95),0 0 22px rgba(255,198,92,.18)}
.portrait-ring{position:absolute;inset:-6px;border-radius:50%;border:1px solid rgba(255,212,121,.42);
  border-top-color:transparent;border-bottom-color:transparent;animation:spin 14s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
#levelBadge{position:absolute;right:-3px;bottom:-2px;width:25px;height:25px;border-radius:50%;
  background:linear-gradient(160deg,#ffe6a5,#c98b2e);color:#231703;font-weight:800;font-size:12px;
  display:grid;place-items:center;border:2px solid #0c1824;font-family:var(--font-display)}
.vitals{width:min(34vw,310px)}
.char-line{display:flex;align-items:baseline;gap:8px;margin-bottom:4px;text-shadow:0 2px 6px #000}
#charName{font-family:var(--font-display);font-size:19px;letter-spacing:.09em;color:var(--gold-pale)}
#charTitle{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#9fb6c2;opacity:.85}
.vbar{position:relative;height:13px;border-radius:7px;background:rgba(4,10,16,.72);
  border:1px solid rgba(255,255,255,.14);overflow:hidden;margin-bottom:5px;
  box-shadow:inset 0 1px 4px rgba(0,0,0,.7)}
.vbar .fill{position:absolute;inset:0;width:100%;transform-origin:left center;border-radius:6px;transition:transform .2s}
.vbar.hp .fill{background:linear-gradient(90deg,#a52038,#ff5d63 55%,#ff9d90);box-shadow:0 0 10px rgba(255,80,90,.5)}
.vbar.mp .fill{background:linear-gradient(90deg,#2a55b8,#63a9ff 55%,#9fe0ff);box-shadow:0 0 10px rgba(90,167,255,.5)}
.vbar.st{height:6px;margin-top:1px;transition:opacity .4s}
.vbar.st .fill{background:linear-gradient(90deg,#c6962d,#ffe29a);box-shadow:0 0 8px rgba(255,214,120,.45)}
.vbar span{position:absolute;inset:0;display:grid;place-items:center;font-size:9px;font-weight:700;
  letter-spacing:.08em;text-shadow:0 1px 2px #000;color:#fff;opacity:.92}

/* ============ compass ============ */
#compassWrap{position:absolute;top:8px;left:50%;transform:translateX(-50%);width:min(46vw,520px);text-align:center}
#compassBar{height:28px;position:relative;overflow:hidden;
  -webkit-mask-image:linear-gradient(90deg,transparent,#000 15%,#000 85%,transparent);
  mask-image:linear-gradient(90deg,transparent,#000 15%,#000 85%,transparent)}
.compass-tick{position:absolute;top:6px;font-size:10px;letter-spacing:.13em;color:rgba(247,242,231,.55);transform:translateX(-50%)}
.compass-tick.major{color:var(--gold);font-size:12px;font-weight:700}
.compass-mark{position:absolute;top:4px;font-size:12px;transform:translateX(-50%);filter:drop-shadow(0 0 5px currentColor)}
#zoneTitle{font-family:var(--font-display);font-size:12px;letter-spacing:.34em;text-transform:uppercase;
  color:rgba(255,235,190,.62);text-shadow:0 2px 8px #000;margin-top:-2px}

/* ============ minimap ============ */
#mapWrap{position:absolute;right:18px;top:14px;width:148px;text-align:center}
#minimap{width:148px;height:148px;border-radius:50%;display:block;
  background:radial-gradient(circle,#163240,#0a1722);box-shadow:0 0 0 2px rgba(255,212,121,.5),0 0 0 6px rgba(8,16,24,.86),0 8px 26px rgba(0,0,0,.55)}
.map-ring{position:absolute;left:50%;top:74px;width:154px;height:154px;transform:translate(-50%,-50%);
  border-radius:50%;border:1px dashed rgba(255,212,121,.2);pointer-events:none}
#goldLine{margin-top:9px;display:flex;align-items:center;justify-content:center;gap:7px;font-size:11px;
  color:#ffe6b0;text-shadow:0 1px 4px #000;font-weight:600}
#goldLine .coin{color:var(--gold);font-size:12px}
#goldLine .sep{width:1px;height:10px;background:rgba(255,255,255,.25)}

/* ============ quest ============ */
#questTracker{position:absolute;right:18px;top:206px;width:230px;padding:10px 12px 11px;
  background:linear-gradient(135deg,rgba(10,22,32,.83),rgba(10,18,27,.6));
  border-left:2px solid var(--gold-deep);backdrop-filter:blur(4px);
  clip-path:polygon(0 0,100% 0,100% calc(100% - 9px),calc(100% - 9px) 100%,0 100%);
  box-shadow:0 6px 22px rgba(0,0,0,.32)}
.q-head{display:flex;gap:7px;align-items:center;font-family:var(--font-display);font-size:13px;
  letter-spacing:.06em;color:var(--gold-pale);margin-bottom:6px}
.q-diamond{font-size:8px;color:var(--gold)}
.q-obj{font-size:11.5px;color:#c8d8dd;display:flex;gap:7px;line-height:1.45;margin-top:3px}
.q-obj .dot{color:var(--teal);font-size:8px;padding-top:3px}
.q-obj.done{color:#7d9a8f;text-decoration:line-through;opacity:.65}
.q-obj .count{color:var(--gold);font-weight:700}

/* ============ boss ============ */
#bossBar{position:absolute;left:50%;top:58px;transform:translateX(-50%);width:min(54vw,580px);text-align:center}
.boss-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:5px;
  font-family:var(--font-display);text-shadow:0 2px 8px #000}
#bossName{font-size:20px;letter-spacing:.14em;color:#ffd9c2;text-transform:uppercase}
#bossPhase{font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:#d5997c}
.boss-track{height:11px;background:rgba(6,8,12,.82);border:1px solid rgba(255,150,120,.35);
  border-radius:2px;position:relative;box-shadow:0 0 24px rgba(240,90,60,.18)}
#bossFill{position:absolute;inset:1px;transform-origin:left;background:linear-gradient(90deg,#7b1728,#e2433c 60%,#ff9a63);
  transition:transform .25s;box-shadow:0 0 14px rgba(255,80,60,.5)}
#bossGhost{position:absolute;inset:1px;transform-origin:left;background:rgba(255,220,190,.35);transition:transform .9s .2s}

/* ============ skills ============ */
#skillbar{position:absolute;left:50%;bottom:20px;transform:translateX(-50%);display:flex;gap:8px;align-items:flex-end}
.skill{position:relative;width:56px;height:56px;border-radius:12px;background:linear-gradient(160deg,rgba(26,44,58,.92),rgba(8,16,24,.94));
  border:1px solid rgba(255,212,121,.32);box-shadow:0 5px 18px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.08);
  display:grid;place-items:center;pointer-events:auto;cursor:pointer;overflow:hidden;transition:transform .12s,border-color .2s}
.skill:hover{transform:translateY(-2px);border-color:rgba(255,225,160,.7)}
.skill.small{width:44px;height:44px;border-radius:10px}
.sk-icon{font-size:23px;filter:drop-shadow(0 0 7px rgba(255,255,255,.18));pointer-events:none}
.skill.small .sk-icon{font-size:18px}
.sk-icon.fire{color:#ffb066;text-shadow:0 0 14px rgba(255,110,40,.8)}
.sk-icon.bolt{color:#ffe594;text-shadow:0 0 14px rgba(255,230,120,.8)}
.sk-icon.ice{color:#a9eeff;text-shadow:0 0 14px rgba(120,220,255,.8)}
.sk-key{position:absolute;right:4px;bottom:2px;font-size:8px;font-weight:800;color:rgba(255,240,210,.7);letter-spacing:.05em}
.sk-cd{position:absolute;inset:0;background:rgba(3,8,14,.74);transform-origin:bottom;transform:scaleY(0);pointer-events:none}
.skill.cooling .sk-cd{transform:scaleY(1);transition:transform .1s linear}
.skill.flash{animation:skillFlash .3s}
@keyframes skillFlash{0%{box-shadow:0 0 0 0 rgba(255,230,160,.6)}100%{box-shadow:0 0 0 14px rgba(255,230,160,0)}}

/* ============ prompts, toast, subtitle ============ */
#interactPrompt{position:absolute;left:50%;top:61%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;
  padding:8px 16px 8px 9px;background:rgba(7,14,20,.82);border:1px solid rgba(255,212,121,.35);border-radius:30px;
  font-size:13px;letter-spacing:.03em;backdrop-filter:blur(6px);box-shadow:0 6px 20px rgba(0,0,0,.4);animation:floatIn .3s}
@keyframes floatIn{from{opacity:0;transform:translate(-50%,7px)}to{opacity:1;transform:translate(-50%,0)}}
.key{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 5px;border-radius:5px;
