export function heightAt(x,z){
  // base rolling hills
  let h = 1.1*Math.sin(x*0.035)*Math.cos(z*0.041) + 0.55*Math.sin(x*0.085+1.2)*Math.cos(z*0.075-0.5) + 0.25*Math.sin(x*0.19)*Math.cos(z*0.16);
  // flatten near village
  const dv = Math.hypot(x, z-28);
  const flat = smoothstep(16, 34, dv); // 0 near village -> flatten
  h *= 0.15 + 0.85*flat;
  // far ridges
  const d = Math.hypot(x,z);
  const ridge = smoothstep(75, 140, d);
  h += ridge * (fbm(x*0.02,z*0.02)*14 + 4);
  // river carve
  const rx = 46 + 9*Math.sin(z*0.032);
  const river = Math.exp(-Math.pow((x-rx)/7,2)) + 0.7*Math.exp(-Math.pow((x-rx-14)/10,2));
  h -= Math.min(1, river) * 3.2;
  // lake near (66,-72)
  const dl = Math.hypot(x-64, z+76);
  h -= Math.max(0, 1 - dl/26) * 4.0;
  // castle plateau at (0,-105)
  const dc = Math.hypot(x, z+108);
  h += Math.max(0, 1 - dc/45) * 5.0;
  // keep spawn area near 0
  return h;
}
