import * as THREE from 'three';
import { toon, makeCloudTexture, makeGlowTexture, rand, TAU, clamp } from '../core/utils.js';

export const SUN_DIR = new THREE.Vector3(0.38, 0.34, -0.86).normalize();

export function buildSky(scene, quality = 2) {
  const group = new THREE.Group();
  group.name = 'sky';
  scene.add(group);

  const uniforms = {
    uZenith: { value: new THREE.Color('#244a7c') },
    uHorizon: { value: new THREE.Color('#ffb47e') },
    uSunColor: { value: new THREE.Color('#ffdca0') },
    uCloud: { value: new THREE.Color('#ffd9cf') },
    uSunDir: { value: SUN_DIR.clone() },
    uTime: { value: 0 },
  };
  const skyMat = new THREE.ShaderMaterial({
    uniforms,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    vertexShader: `
      varying vec3 vDir;
      void main(){
        vDir = normalize(position);
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: `
      uniform vec3 uZenith, uHorizon, uSunColor, uCloud, uSunDir;
      uniform float uTime;
      varying vec3 vDir;
      float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
      float noise(vec2 p){
        vec2 i = floor(p), f = fract(p);
        vec2 u = f*f*(3.0-2.0*f);
        return mix(mix(hash(i), hash(i+vec2(1,0)), u.x), mix(hash(i+vec2(0,1)), hash(i+vec2(1,1)), u.x), u.y);
      }
      float fbm(vec2 p){
        float v = 0.0, a = 0.55;
        for(int i=0;i<5;i++){ v += noise(p)*a; p *= 2.03; a *= 0.5; }
        return v;
      }
      void main(){
        vec3 d = normalize(vDir);
        float up = clamp(d.y, 0.0, 1.0);
        vec3 col = mix(uHorizon, uZenith, pow(up, 0.48));
        // warm horizon band
        col = mix(col, vec3(1.0, 0.72, 0.48), smoothstep(0.18, 0.0, abs(d.y)) * 0.25);
        float sd = max(dot(d, uSunDir), 0.0);
        col += uSunColor * pow(sd, 6.0) * 0.32;
        col += uSunColor * pow(sd, 60.0) * 0.55;
        col += vec3(1.0,0.95,0.85) * smoothstep(0.9986, 0.9994, sd) * 1.4;
        // painted cloud strata
        vec2 cp = d.xz / max(d.y + 0.28, 0.1) * 2.4 + vec2(uTime*0.006, uTime*0.002);
        float n = fbm(cp * vec2(1.0, 2.2));
        float band = smoothstep(0.53, 0.72, n) * smoothstep(0.02, 0.13, d.y) * (1.0 - smoothstep(0.42, 0.8, d.y));
        float band2 = smoothstep(0.58, 0.8, fbm(cp*2.3 + 4.0)) * smoothstep(0.12, 0.22, d.y) * (1.0 - smoothstep(0.3, 0.55, d.y));
        col = mix(col, uCloud, band * 0.36 + band2 * 0.22);
        // subtle dithering to avoid banding
        col += (hash(gl_FragCoord.xy) - 0.5) * 0.012;
        gl_FragColor = vec4(col, 1.0);
      }`,
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(760, 32, 20), skyMat);
  sky.renderOrder = -100;
  sky.frustumCulled = false;
  group.add(sky);

  // sun halo
  const glowTex = makeGlowTexture('#ffffff');
  const sunHalo = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTex, color: 0xffc47a, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, fog: false, opacity: .7,
  }));
  sunHalo.scale.setScalar(210);
  sunHalo.position.copy(SUN_DIR).multiplyScalar(620);
  sunHalo.renderOrder = -90;
  group.add(sunHalo);
  const sunCore = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTex, color: 0xfff3cf, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
  }));
  sunCore.scale.setScalar(52);
  sunCore.position.copy(SUN_DIR).multiplyScalar(618);
  sunCore.renderOrder = -90;
  group.add(sunCore);

  // pale companion moon, for a distinct Aetheria sky
  const moon = new THREE.Mesh(new THREE.CircleGeometry(16, 32), new THREE.MeshBasicMaterial({ color: 0xd9e4ff, transparent: true, opacity: .5, fog: false }));
  moon.position.set(-240, 165, -520);
  moon.lookAt(0, 0, 0);
  moon.renderOrder = -89;
  group.add(moon);
  const moonGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: 0x9fb6ff, transparent: true, opacity: .22, blending: THREE.AdditiveBlending, depthWrite: false, fog: false }));
  moonGlow.scale.setScalar(90); moonGlow.position.copy(moon.position); moonGlow.renderOrder = -89;
  group.add(moonGlow);

  /* ---------------- drifting cloud billboards ---------------- */
  const cloudTex = makeCloudTexture();
  const clouds = [];
  const N = quality >= 2 ? 16 : 9;
  for (let i = 0; i < N; i++) {
    const m = new THREE.SpriteMaterial({ map: cloudTex, transparent: true, opacity: rand(.42, .8), depthWrite: false, fog: false, color: new THREE.Color().setHSL(rand(.02, .08), rand(.25, .55), rand(.82, .97)) });
    const s = new THREE.Sprite(m);
    const a = rand(0, TAU), r = rand(180, 430);
    s.position.set(Math.cos(a) * r, rand(52, 165), Math.sin(a) * r);
    const sc = rand(70, 170);
    s.scale.set(sc, sc * .55, 1);
    s.renderOrder = -85;
    s.userData = { speed: rand(1.2, 4.2), baseY: s.position.y, phase: rand(0, TAU) };
    group.add(s); clouds.push(s);
  }

  /* ---------------- distant mountain ring ---------------- */
  const mountains = new THREE.Group();
  const rockMat = new THREE.MeshLambertMaterial({ color: 0x5d6785 });
  const snowMat = new THREE.MeshLambertMaterial({ color: 0xd7c9d8 });
  for (let i = 0; i < 26; i++) {
    const a = (i / 26) * TAU + rand(-.08, .08);
    const r = rand(225, 300);
    const h = rand(36, 92);
    const w = rand(35, 70);
    const g = new THREE.Group();
    const peak = new THREE.Mesh(new THREE.ConeGeometry(w, h, 5), rockMat);
    peak.position.y = h / 2; peak.rotation.y = rand(0, TAU);
    g.add(peak);
    const cap = new THREE.Mesh(new THREE.ConeGeometry(w * .42, h * .34, 5), snowMat);
    cap.position.y = h - h * .16; cap.rotation.y = peak.rotation.y;
    g.add(cap);
    g.position.set(Math.cos(a) * r, -8 + h / 2, Math.sin(a) * r);
    mountains.add(g);
  }
  group.add(mountains);

  /* ---------------- floating crystal isles ---------------- */
  const isles = [];
  const isleData = [
    { a: 0.6, r: 195, y: 74, s: 1.5 },
    { a: 2.2, r: 235, y: 58, s: 1.1 },
    { a: 4.1, r: 210, y: 88, s: .85 },
    { a: 5.4, r: 175, y: 48, s: .6 },
  ];
  for (let i = 0; i < isleData.length; i++) {
    const d = isleData[i];
    const isle = new THREE.Group();
    const rock = new THREE.Mesh(new THREE.ConeGeometry(13, 22, 7), new THREE.MeshLambertMaterial({ color: 0x6b5d72 }));
    rock.rotation.x = Math.PI; rock.position.y = -10;
    const top = new THREE.Mesh(new THREE.CylinderGeometry(13, 11, 3, 7), new THREE.MeshLambertMaterial({ color: 0x6aa15c }));
    top.position.y = 1.5;
    isle.add(rock, top);
    // trees / crystals
    for (let k = 0; k < 4; k++) {
      const cr = new THREE.Mesh(new THREE.OctahedronGeometry(rand(1.2, 2.8), 0), new THREE.MeshBasicMaterial({ color: 0x9ce9ff }));
      cr.position.set(rand(-6, 6), rand(4, 9), rand(-6, 6));
      cr.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
      isle.add(cr);
    }
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: 0x8ce8ff, transparent: true, opacity: .32, blending: THREE.AdditiveBlending, depthWrite: false, fog: false }));
    glow.scale.setScalar(42); glow.position.y = 3; isle.add(glow);
    // vines
    for (let k = 0; k < 3; k++) {
      const vine = new THREE.Mesh(new THREE.CylinderGeometry(.12, .04, rand(8, 18), 3), new THREE.MeshLambertMaterial({ color: 0x4f7f4b }));
      vine.position.set(rand(-8, 8), -rand(4, 10), rand(-8, 8)); isle.add(vine);
    }
    isle.position.set(Math.cos(d.a) * d.r, d.y, Math.sin(d.a) * d.r);
    isle.scale.setScalar(d.s);
    isle.rotation.y = rand(0, TAU);
    isle.userData = { baseY: d.y, phase: rand(0, TAU) };
    group.add(isle); isles.push(isle);
  }

  /* ---------------- distant birds ---------------- */
  const birds = [];
  const birdMat = new THREE.LineBasicMaterial({ color: 0x2c2a3c, transparent: true, opacity: .55, fog: false });
  for (let i = 0; i < 8; i++) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array([-2, 0, 0, 0, .5, 0, 2, 0, 0]), 3));
    const line = new THREE.Line(geo, birdMat);
    const a = rand(0, TAU), r = rand(60, 200);
    line.position.set(Math.cos(a) * r, rand(28, 58), Math.sin(a) * r);
    line.scale.setScalar(rand(1.2, 2.4));
    line.userData = { a, r, speed: rand(.02, .05), phase: rand(0, TAU) };
    group.add(line); birds.push(line);
  }

  let t = 0;
  const tmp = new THREE.Vector3();
  return {
    group,
    sunDir: SUN_DIR,
    update(dt, time) {
      t = time;
      uniforms.uTime.value = time;
      for (const c of clouds) {
        c.position.x += c.userData.speed * dt;
        if (c.position.x > 460) c.position.x = -460;
        c.position.y = c.userData.baseY + Math.sin(time * .08 + c.userData.phase) * 4;
      }
      for (const i of isles) {
        i.position.y = i.userData.baseY + Math.sin(time * .18 + i.userData.phase) * 2.4;
        i.rotation.y += dt * .012;
      }
      for (const b of birds) {
        b.userData.a += dt * b.userData.speed;
        b.position.x = Math.cos(b.userData.a) * b.userData.r;
        b.position.z = Math.sin(b.userData.a) * b.userData.r;
        b.position.y += Math.sin(time * 1.4 + b.userData.phase) * dt * .8;
        b.rotation.y = -b.userData.a + Math.PI / 2;
        b.rotation.z = Math.sin(time * 3 + b.userData.phase) * .18;
      }
      sunHalo.position.copy(SUN_DIR).multiplyScalar(620);
      sunCore.position.copy(SUN_DIR).multiplyScalar(618);
    },
  };
}

import * as THREE from 'three';
import { clamp, smoothstep, fbm, valueNoise, makeGroundTexture, makeStoneTexture, rand, TAU, toon } from '../core/utils.js';

export const WATER_LEVEL = -1.05;
export const WORLD_RADIUS = 150;

export const riverX = z => 46 + 8 * Math.sin(z * 0.030) + 2.2 * Math.sin(z * 0.11 + 0.7);
const LAKE = { x: 58, z: -78, r: 20 };

/** Analytic terrain height — used by mesh, movement, props and AI. */
export function heightAt(x, z) {
  let h = 1.35 * Math.sin(x * 0.034 + 0.4) * Math.cos(z * 0.039 - 0.2)
        + 0.55 * Math.sin(x * 0.083 + 1.7) * Math.cos(z * 0.071 + 0.5)
        + 0.22 * Math.sin(x * 0.19 + 0.3) * Math.cos(z * 0.16 + 1.1);

  // flatten village bowl
  const dv = Math.hypot(x, z - 32);
  const flat = smoothstep(15, 34, dv);
  h *= 0.12 + 0.88 * flat;

  // far ridgeline: land rises toward the borders
  const d = Math.hypot(x, z);
  const ridge = smoothstep(78, 148, d);
  h += ridge * (6 + fbm(x * 0.018 + 10, z * 0.018 - 4, 3) * 19);

  // castle plateau
  const dc = Math.hypot(x, z + 105);
  h += Math.max(0, 1 - dc / 46) * 4.6;

  // river channel
  const rx = riverX(z);
  const riverD = Math.abs(x - rx);
  const river = Math.max(0, 1 - riverD / 7.5);
  h -= river * river * 3.1;

  // lake bowl
  const dl = Math.hypot(x - LAKE.x, z - LAKE.z);
  h -= Math.max(0, 1 - dl / LAKE.r) * 4.4;
  if (dl < LAKE.r + 6) h -= (1 - smoothstep(LAKE.r - 2, LAKE.r + 6, dl)) * 1.2;

  // shallow stream joining river -> lake for a nice silhouette
  const st = Math.abs(z + 40 + Math.sin(x * 0.08) * 4) < 3 ? Math.max(0, 1 - Math.abs(x - 48) / 16) : 0;
  h -= st * 1.4;

  // keep a gentle clearing at spawn
  const ds = Math.hypot(x, z - 48);
  if (ds < 9) h *= smoothstep(4, 9, ds) * 0.8 + 0.2;

  return h;
}

export function terrainNormal(x, z, e = 0.5) {
  const hL = heightAt(x - e, z), hR = heightAt(x + e, z);
  const hD = heightAt(x, z - e), hU = heightAt(x, z + e);
  return new THREE.Vector3(hL - hR, 2 * e, hD - hU).normalize();
}

/* ---------------- roads ---------------- */
export const ROADS = [
  { width: 4.4, pts: [[0, 51], [0, 32], [1, 12], [3, -8], [3, -28], [1, -52], [0, -74], [0, -92], [0, -98]] },
  { width: 3.0, pts: [[0, 32], [-14, 34], [-28, 38], [-34, 42]] },
  { width: 3.0, pts: [[1, 14], [16, 10], [33, 6], [46, 4], [58, 0], [68, -8]] },
  { width: 3.0, pts: [[3, -8], [-14, -12], [-30, -18], [-46, -24], [-58, -30]] },
  { width: 2.4, pts: [[-46, -24], [-40, -36], [-36, -46], [-34, -52]] },
  { width: 2.4, pts: [[-58, -30], [-70, -38], [-80, -46], [-86, -54]] },
  { width: 2.4, pts: [[2, -30], [16, -38], [28, -46], [35, -53], [39, -58]] },
  { width: 2.4, pts: [[-58, -30], [-66, -22], [-64, -8], [-68, 4], [-76, 9]] },
  { width: 2.4, pts: [[68, -8], [64, -24], [60, -44], [58, -60], [58, -68]] },
];

function pointSegDist(px, pz, ax, az, bx, bz) {
  const dx = bx - ax, dz = bz - az;
  const t = clamp(((px - ax) * dx + (pz - az) * dz) / (dx * dx + dz * dz || 1), 0, 1);
  return Math.hypot(px - (ax + dx * t), pz - (az + dz * t));
}
export function roadDistance(x, z) {
  let best = 999;
  for (const r of ROADS) for (let i = 0; i < r.pts.length - 1; i++) {
    const a = r.pts[i], b = r.pts[i + 1];
    best = Math.min(best, pointSegDist(x, z, a[0], a[1], b[0], b[1]) - r.width * .5);
  }
  return best;
}
export function surfaceAt(x, z) {
  const dl = Math.hypot(x - LAKE.x, z - LAKE.z);
  if (dl < LAKE.r - 2) return 'water';
  if (Math.abs(x - riverX(z)) < 6.2 && heightAt(x, z) < WATER_LEVEL + .6) return 'water';
  const rd = roadDistance(x, z);
  if (rd < 0.4) return 'stone';
  if (rd < 1.6) return 'dirt';
  return 'grass';
}
export function isWater(x, z) {
  return heightAt(x, z) < WATER_LEVEL + 0.15;
}

/* ---------------- terrain mesh ---------------- */
export function buildTerrain(scene, quality = 2) {
  const size = 340;
  const seg = quality >= 2 ? 170 : 120;
  const geo = new THREE.PlaneGeometry(size, size, seg, seg);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  const greens = ['#6aa25a', '#76ad61', '#5e9452', '#83b96b', '#679b58'].map(h => new THREE.Color(h));
  const meadow = new THREE.Color('#a4b866');
  const sand = new THREE.Color('#c8ae7c');
  const rock = new THREE.Color('#837e86');
  const deep = new THREE.Color('#31564a');

  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    const h = heightAt(x, z);
    pos.setY(i, h);
    const n = fbm(x * 0.045 + 3, z * 0.045 - 2, 3);
    const n2 = fbm(x * 0.012 + 20, z * 0.012 + 5, 2);
    c.copy(greens[(n * greens.length) | 0] || greens[0]);
    c.lerp(meadow, clamp((n2 - .48) * 2.2, 0, .55));
    const rx = riverX(z);
    const nearBank = Math.abs(x - rx) < 9 || Math.hypot(x - LAKE.x, z - LAKE.z) < LAKE.r + 5;
    if (nearBank) c.lerp(sand, clamp((WATER_LEVEL + 1.9 - h) * .55, 0, .8));
    if (h < WATER_LEVEL) c.lerp(deep, clamp((WATER_LEVEL - h) * .44, 0, .85));
    if (h > 7.5) c.lerp(rock, clamp((h - 7.5) * .16, 0, .8));
    if (h > 15) c.lerp(new THREE.Color('#a7a0aa'), clamp((h - 15) * .08, 0, .5));
    const tint = .92 + valueNoise(x * .3, z * .3) * .16;
    c.multiplyScalar(tint);
    colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  const tex = makeGroundTexture();
  tex.repeat.set(38, 38);
  const mat = new THREE.MeshToonMaterial({ map: tex, vertexColors: true, gradientMap: null });
  mat.gradientMap = null;
  const mesh = new THREE.Mesh(geo, new THREE.MeshLambertMaterial({ map: tex, vertexColors: true }));
  mesh.receiveShadow = true;
  mesh.name = 'terrain';
  scene.add(mesh);

  // darker painterly undergrowth patches
  const patchMat = new THREE.MeshBasicMaterial({ color: 0x2f5a3a, transparent: true, opacity: .12, depthWrite: false });
  for (let i = 0; i < 26; i++) {
    const a = rand(0, TAU), r = rand(20, 120);
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (isWater(x, z)) continue;
    const m = new THREE.Mesh(new THREE.CircleGeometry(rand(4, 13), 12), patchMat);
    m.rotation.x = -Math.PI / 2;
    m.position.set(x, heightAt(x, z) + .04, z);
    m.scale.y = rand(.5, 1.2);
    m.renderOrder = 1;
    scene.add(m);
  }
  return { mesh, heightAt, surfaceAt };
}

/* ---------------- stylized water ---------------- */
export function buildWater(scene) {
  const geo = new THREE.PlaneGeometry(340, 340, 96, 96);
  geo.rotateX(-Math.PI / 2);
  const uniforms = {
    uTime: { value: 0 },
    uDeep: { value: new THREE.Color('#1a667c') },
    uShallow: { value: new THREE.Color('#58d9d0') },
    uSun: { value: new THREE.Color('#ffe9b0') },
    uSunDir: { value: new THREE.Vector3(.38, .34, -.86).normalize() },
  };
  const mat = new THREE.ShaderMaterial({
    uniforms,
    transparent: true,
    depthWrite: false,
    vertexShader: `
      uniform float uTime;
      varying vec3 vWorld;
      varying vec2 vUv;
      void main(){
        vUv = uv;
        vec3 p = position;
        p.y += sin(p.x*0.32 + uTime*1.2)*0.06 + cos(p.z*0.28 - uTime*0.9)*0.055;
        vec4 wp = modelMatrix * vec4(p, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: `
      uniform float uTime; uniform vec3 uDeep, uShallow, uSun, uSunDir;
      varying vec3 vWorld; varying vec2 vUv;
      float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7)))*43758.5453); }
      float noise(vec2 p){
        vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.0-2.0*f);
        return mix(mix(hash(i),hash(i+vec2(1,0)),u.x), mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),u.x),u.y);
      }
      void main(){
        vec2 p = vWorld.xz;
        float n = noise(p*0.9 + vec2(uTime*0.18, uTime*0.1));
        float n2 = noise(p*2.6 - vec2(uTime*0.3, -uTime*0.22));
        // painterly bands
        float bands = smoothstep(0.52,0.62, sin(p.x*0.42 + p.z*0.22 + n*2.4 + uTime*0.9)*0.5+0.5);
        vec3 col = mix(uDeep, uShallow, 0.36 + n*0.34 + bands*0.18);
        // sky reflection tint
        col = mix(col, vec3(0.72,0.88,0.95), 0.10);
        // stylised glitter
        float spark = smoothstep(0.78,0.94, noise(p*7.0 + vec2(uTime*0.5, -uTime*0.4)) * (0.5 + 0.5*n2));
        col += uSun * spark * 0.7;
        // foam contours
        float foam = smoothstep(0.72, 0.84, n2) * smoothstep(0.4, 0.9, n);
        col = mix(col, vec3(0.92,1.0,0.99), foam*0.35);
        // view fresnel
        vec3 v = normalize(cameraPosition - vWorld);
        float fres = pow(1.0 - clamp(v.y, 0.0, 1.0), 2.2);
        col = mix(col, vec3(0.78,0.92,1.0), fres*0.28);
        gl_FragColor = vec4(col, 0.88);
      }`,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.y = WATER_LEVEL;
  mesh.name = 'water';
  mesh.renderOrder = 2;
  scene.add(mesh);

  // soft foam edge strips along the river + lake rim
  const foamMat = new THREE.MeshBasicMaterial({ color: 0xd8fff6, transparent: true, opacity: .18, depthWrite: false, side: THREE.DoubleSide });
  const foamPts = [];
  for (let z = -130; z < 130; z += 4) {
    const rx = riverX(z);
    foamPts.push([rx, z, 1]);
  }
  const foamGeo = new THREE.BufferGeometry();
  const verts = [];
  for (let i = 0; i < foamPts.length - 1; i++) {
    const [x1, z1] = foamPts[i], [x2, z2] = foamPts[i + 1];
    const w = 1.5;
    verts.push(x1 - w, WATER_LEVEL + .03, z1, x1 + w, WATER_LEVEL + .03, z1, x2 + w, WATER_LEVEL + .03, z2);
    verts.push(x1 - w, WATER_LEVEL + .03, z1, x2 + w, WATER_LEVEL + .03, z2, x2 - w, WATER_LEVEL + .03, z2);
  }
  foamGeo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  const foam = new THREE.Mesh(foamGeo, foamMat);
  foam.renderOrder = 3;
  scene.add(foam);

  return {
    mesh,
    update(dt, time) { uniforms.uTime.value = time; },
  };
}

/* ---------------- roads ---------------- */
export function buildRoads(scene) {
  const tex = makeStoneTexture();
  tex.repeat.set(2, 2);
  const mat = new THREE.MeshLambertMaterial({ map: tex, color: 0xd6bd92, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
  const group = new THREE.Group(); group.name = 'roads';
  for (const road of ROADS) {
    const pts = [];
    for (let i = 0; i < road.pts.length - 1; i++) {
      const a = road.pts[i], b = road.pts[i + 1];
      const n = Math.max(2, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / 3));
      for (let k = 0; k < n; k++) {
        const t = k / n;
        pts.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
      }
    }
    pts.push(road.pts[road.pts.length - 1]);
    const positions = [], uvs = [];
    let dist = 0;
    for (let i = 0; i < pts.length; i++) {
      const p = pts[i];
      const prev = pts[Math.max(0, i - 1)], next = pts[Math.min(pts.length - 1, i + 1)];
      let dx = next[0] - prev[0], dz = next[1] - prev[1];
      const len = Math.hypot(dx, dz) || 1; dx /= len; dz /= len;
      const nx = -dz, nz = dx;
      const w = road.width * .5;
      const y = heightAt(p[0], p[1]) + 0.06;
      const y2 = heightAt(p[0] + nx * w, p[1] + nz * w) + 0.06;
      const y3 = heightAt(p[0] - nx * w, p[1] - nz * w) + 0.06;
      positions.push(p[0] + nx * w, Math.max(y, y2) + .02, p[1] + nz * w);
      positions.push(p[0] - nx * w, Math.max(y, y3) + .02, p[1] - nz * w);
      if (i > 0) dist += Math.hypot(p[0] - pts[i - 1][0], p[1] - pts[i - 1][1]);
      const v = dist / 8;
      uvs.push(0, v, 1, v);
    }
    const idx = [];
    for (let i = 0; i < pts.length - 1; i++) {
      const a = i * 2, b = a + 1, c = a + 2, d = a + 3;
      idx.push(a, b, c, b, d, c);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    g.setIndex(idx);
    g.computeVertexNormals();
    const mesh = new THREE.Mesh(g, mat);
    mesh.receiveShadow = true;
    group.add(mesh);
  }
  scene.add(group);
  return group;
}

import * as THREE from 'three';
import { mergeGeometries } from '../../vendor/BufferGeometryUtils.js';
import {
  toon, rand, randInt, mulberry32, TAU, makeGrassTexture, makeFlowerTexture,
  makeSoftTexture, addOutline, clamp, fbm
} from '../core/utils.js';
import { heightAt, isWater, roadDistance, WORLD_RADIUS } from './terrain.js';

function windMaterial(color, strength = 0.05) {
  const m = toon(color, { rim: 0.1, rimColor: 0xdfffe4 });
  m.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = { value: 0 };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;')
      .replace('#include <project_vertex>', `
        #ifdef USE_INSTANCING
          float phase = instanceMatrix[3][0] * 0.16 + instanceMatrix[3][2] * 0.13;
        #else
          float phase = 0.0;
        #endif
        float sway = sin(uTime * 0.85 + phase) * ${strength.toFixed(3)};
        transformed.x += sway * max(transformed.y, 0.0);
        transformed.z += cos(uTime * 0.7 + phase) * ${(strength * 0.7).toFixed(3)} * max(transformed.y, 0.0);
        #include <project_vertex>`);
    m.userData.shader = shader;
  };
  m.customProgramCacheKey = () => 'wind-' + strength;
  return m;
}

function makeInstance(geo, mat, entries, { cast = false, receive = false } = {}) {
  const mesh = new THREE.InstancedMesh(geo, mat, entries.length);
  const dummy = new THREE.Object3D();
  const col = new THREE.Color();
  entries.forEach((e, i) => {
    dummy.position.set(e.x, e.y ?? heightAt(e.x, e.z), e.z);
    dummy.rotation.set(e.rx || 0, e.ry ?? rand(0, TAU), e.rz || 0);
    const s = e.s ?? 1;
    dummy.scale.set(e.sx ?? s, e.sy ?? s, e.sz ?? s);
    dummy.updateMatrix();
    mesh.setMatrixAt(i, dummy.matrix);
    if (e.color !== undefined) mesh.setColorAt(i, col.set(e.color));
  });
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  mesh.castShadow = cast; mesh.receiveShadow = receive;
  mesh.instanceMatrix.needsUpdate = true;
  mesh.computeBoundingSphere();
  return mesh;
}

function treeCanopyGeo(blobs) {
  const parts = [];
  for (const [x, y, z, r] of blobs) {
    const g = new THREE.IcosahedronGeometry(r, 1);
    g.scale(1, .82, 1);
    g.translate(x, y, z);
    parts.push(g);
  }
  return mergeGeometries(parts);
}

export function buildVegetation(scene, exclusions = [], quality = 2) {
  const rnd = mulberry32(9231);
  const group = new THREE.Group(); group.name = 'vegetation';
  scene.add(group);

  const blocked = (x, z, pad = 0) => {
    if (isWater(x, z)) return true;
    if (Math.hypot(x, z) > WORLD_RADIUS - 8) return true;
    if (roadDistance(x, z) < 3.2 + pad) return true;
    for (const e of exclusions) if (Math.hypot(x - e.x, z - e.z) < e.r + pad) return true;
    return false;
  };

  /* ---------- trees ---------- */
  const roundTrunk = new THREE.CylinderGeometry(.17, .3, 3.4, 6).translate(0, 1.7, 0);
  const roundCanopy = treeCanopyGeo([[0, 3.9, 0, 1.5], [.8, 4.6, .4, 1.05], [-.85, 4.4, -.3, 1.0], [.1, 5.5, -.2, .95], [-.1, 4.0, .95, .85]]);
  const pineTrunk = new THREE.CylinderGeometry(.14, .26, 3.4, 6).translate(0, 1.7, 0);
  const pineParts = [];
  for (let i = 0; i < 4; i++) {
    const g = new THREE.ConeGeometry(1.5 - i * .27, 1.9, 7);
    g.translate(0, 3.1 + i * 1.05, 0); pineParts.push(g);
  }
  const pineCanopy = mergeGeometries(pineParts);
  const cherryCanopy = treeCanopyGeo([[0, 3.8, 0, 1.65], [1, 4.4, .3, 1.1], [-.9, 4.5, -.4, 1.05], [0, 5.6, -.3, 1.0], [.2, 4.1, 1.0, .9]]);
  const oliveCanopy = treeCanopyGeo([[0, 4.0, 0, 1.35], [.9, 5.0, .2, .95], [-.8, 4.7, -.5, .9], [-.2, 5.8, .3, .75]]);

  const treeSpots = [];
  const forestCenters = [[-100, 35, 24], [105, -22, 22], [-78, 88, 20], [96, 66, 22], [-112, -60, 18], [70, 95, 16], [125, 18, 20], [-60, 110, 18]];
  let attempts = 0;
  while (treeSpots.length < (quality >= 2 ? 300 : 190) && attempts < 3200) {
    attempts++;
    const a = rnd() * TAU, r = Math.sqrt(rnd()) * (WORLD_RADIUS - 12);
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    const dv = Math.hypot(x, z - 32);
    if (dv < 22) continue;
    if (blocked(x, z, 1)) continue;
    let forestBias = 0.35;
    for (const [fx, fz, fr] of forestCenters) {
      const d = Math.hypot(x - fx, z - fz);
      if (d < fr) forestBias += (1 - d / fr) * 0.8;
    }
    const n = fbm(x * 0.036 + 5, z * 0.036 + 2, 3);
    if (rnd() > forestBias * 0.55 + n * 0.6) continue;
    // keep a rough clearing for sightlines along the road
    if (Math.abs(x) < 8 && z > -90 && z < 55 && rnd() < .7) continue;
    treeSpots.push({ x, z, r: rnd(), scale: rand(.8, 1.35), rot: rnd() * TAU });
  }

  const deciduous = [], pines = [], cherries = [], olives = [], trunks = [], pineTrunks = [], cherryTrunks = [], oliveTrunks = [];
  const shadows = [];
  for (const t of treeSpots) {
    const y = heightAt(t.x, t.z);
    const kind = t.r;
    const color = new THREE.Color();
    if (kind < .3) {
      color.setHSL(rand(.24, .32), rand(.38, .56), rand(.34, .48));
      olives.push({ x: t.x, z: t.z, y, s: t.scale, ry: t.rot, color });
      oliveTrunks.push({ x: t.x, z: t.z, y, s: t.scale, ry: t.rot, color: new THREE.Color().setHSL(.08, .35, rand(.24, .34)) });
    } else if (kind < .56) {
      color.setHSL(rand(.07, .12), rand(.45, .62), rand(.38, .5));
      pines.push({ x: t.x, z: t.z, y, s: t.scale, ry: t.rot, color });
      pineTrunks.push({ x: t.x, z: t.z, y, s: t.scale, ry: t.rot, color: new THREE.Color().setHSL(.07, .3, .27) });
    } else if (kind < .66) {
      color.setHSL(rand(.93, .98), rand(.4, .56), rand(.74, .85));
      cherries.push({ x: t.x, z: t.z, y, s: t.scale, ry: t.rot, color });
      cherryTrunks.push({ x: t.x, z: t.z, y, s: t.scale, ry: t.rot, color: new THREE.Color().setHSL(.06, .22, .3) });
    } else {
      color.setHSL(rand(.19, .3), rand(.4, .62), rand(.36, .51));
      if (rnd() < .18) color.setHSL(rand(.06, .1), rand(.55, .7), rand(.48, .58)); // autumn gold
      deciduous.push({ x: t.x, z: t.z, y, s: t.scale, ry: t.rot, color });
      trunks.push({ x: t.x, z: t.z, y, s: t.scale, ry: t.rot, color: new THREE.Color().setHSL(.07, .34, rand(.23, .32)) });
    }
    shadows.push({ x: t.x, z: t.z, y: y + .03, s: t.scale * 2.4, rx: -Math.PI / 2, ry: 0, color: 0x12331f });
  }

  const trunkMat = toon(0xffffff, { rim: 0.06, rimColor: 0xffe0b0 });
  const leafMat = windMaterial(0xffffff, .045);
  const leafMat2 = windMaterial(0xffffff, .025);

  group.add(makeInstance(roundCanopy, leafMat, deciduous));
  group.add(makeInstance(roundTrunk, trunkMat, trunks));
  group.add(makeInstance(pineCanopy, leafMat2, pines));
  group.add(makeInstance(pineTrunk, trunkMat, pineTrunks));
  group.add(makeInstance(cherryCanopy, leafMat, cherries));
  group.add(makeInstance(roundTrunk, trunkMat, cherryTrunks));
  group.add(makeInstance(oliveCanopy, leafMat2, olives));
  group.add(makeInstance(roundTrunk, trunkMat, oliveTrunks));

  const shadowMat = new THREE.MeshBasicMaterial({ color: 0x18351f, transparent: true, opacity: .22, depthWrite: false });
  const shadowMesh = makeInstance(new THREE.CircleGeometry(1, 10), shadowMat, shadows);
  shadowMesh.renderOrder = 1;
  group.add(shadowMesh);

  /* ---------- rocks ---------- */
  const rockGeo = new THREE.DodecahedronGeometry(.8, 0);
  const rockEntries = [];
  const rockColors = ['#8b8892', '#77737f', '#9a94a0', '#66626e', '#a49aa0'];
  for (let i = 0; i < (quality >= 2 ? 220 : 140); i++) {
    const a = rnd() * TAU, r = Math.sqrt(rnd()) * (WORLD_RADIUS - 6);
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (blocked(x, z, -.5)) continue;
    if (Math.hypot(x, z - 32) < 18) continue;
    const s = rand(.35, 1.5);
    rockEntries.push({
      x, z, y: heightAt(x, z) + s * .25, s, sy: s * rand(.6, 1.1),
      ry: rnd() * TAU, rx: rand(0, .6), color: rockColors[(rnd() * rockColors.length) | 0],
    });
  }
  group.add(makeInstance(rockGeo, toon(0xffffff, { rim: .16, rimColor: 0xcfe4ff }), rockEntries, { cast: false, receive: true }));

  // big boulder clusters near world rim
  const boulders = [];
  for (let i = 0; i < 26; i++) {
    const a = (i / 26) * TAU + rand(-.1, .1);
    const r = rand(132, 152);
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    const s = rand(3, 9);
    boulders.push({ x, z, y: heightAt(x, z) + s * .3, sx: s, sy: s * rand(.9, 1.6), sz: s, ry: rnd() * TAU, rx: rand(-.3, .3), color: 0x7e7888 });
  }
  group.add(makeInstance(rockGeo, toon(0xffffff, { rim: .12, rimColor: 0xbfd4ff }), boulders));

  /* ---------- bushes ---------- */
  const bushGeo = treeCanopyGeo([[0, .55, 0, .75], [.6, .5, .2, .55], [-.55, .45, -.1, .6]]);
  const bushes = [];
  for (let i = 0; i < (quality >= 2 ? 200 : 120); i++) {
    const a = rnd() * TAU, r = Math.sqrt(rnd()) * 120;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (blocked(x, z, -1)) continue;
    if (Math.hypot(x, z - 32) < 17) continue;
    bushes.push({ x, z, y: heightAt(x, z), s: rand(.55, 1.3), ry: rnd() * TAU, color: new THREE.Color().setHSL(rand(.22, .32), rand(.35, .55), rand(.3, .44)) });
  }
  group.add(makeInstance(bushGeo, leafMat2, bushes));

  /* ---------- grass tufts ---------- */
  const grassTex = makeGrassTexture();
  const grassMat = new THREE.MeshLambertMaterial({ map: grassTex, transparent: true, alphaTest: .35, side: THREE.DoubleSide, depthWrite: true, color: 0xffffff });
  const bladeGeo = mergeGeometries([
    new THREE.PlaneGeometry(1.15, .95).translate(0, .47, 0),
    new THREE.PlaneGeometry(1.15, .95).rotateY(Math.PI / 2).translate(0, .47, 0),
  ]);
  const tufts = [];
  const N = quality >= 2 ? 3400 : 1400;
  for (let i = 0; i < N; i++) {
    const a = rnd() * TAU, r = Math.sqrt(rnd()) * 118;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (isWater(x, z) || roadDistance(x, z) < 1.6) continue;
    if (Math.hypot(x - 0, z - 32) < 10) continue;
    let blockedByPoi = false;
    for (const e of exclusions) if (Math.hypot(x - e.x, z - e.z) < e.r * .8) { blockedByPoi = true; break; }
    if (blockedByPoi) continue;
    tufts.push({
      x, z, y: heightAt(x, z), s: rand(.62, 1.3), sy: rand(.7, 1.5), ry: rnd() * TAU,
      color: new THREE.Color().setHSL(rand(.2, .3), rand(.35, .6), rand(.42, .62)),
    });
  }
  const grassMesh = makeInstance(bladeGeo, grassMat, tufts);
  grassMesh.receiveShadow = false;
  group.add(grassMesh);

  /* ---------- flowers ---------- */
  const flowerColors = ['#ffd6e6', '#ffe58a', '#c9b3ff', '#ffb59b', '#a8e8ff'];
  const flowerGeo = mergeGeometries([
    new THREE.PlaneGeometry(.55, .55).translate(0, .3, 0),
    new THREE.PlaneGeometry(.55, .55).rotateY(Math.PI / 2).translate(0, .3, 0),
  ]);
  flowerColors.forEach((col, idx) => {
    const tex = makeFlowerTexture(col);
    const mat = new THREE.MeshLambertMaterial({ map: tex, transparent: true, alphaTest: .4, side: THREE.DoubleSide, depthWrite: true });
    const arr = [];
    for (let i = 0; i < (quality >= 2 ? 150 : 60); i++) {
      const a = rnd() * TAU, r = Math.sqrt(rnd()) * 100;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (isWater(x, z) || roadDistance(x, z) < 1.5) continue;
      arr.push({ x, z, y: heightAt(x, z), s: rand(.7, 1.4), ry: rnd() * TAU });
    }
    group.add(makeInstance(flowerGeo, mat, arr));
  });

  /* ---------- reeds along water ---------- */
  const reedMat = new THREE.MeshLambertMaterial({ map: grassTex, transparent: true, alphaTest: .3, side: THREE.DoubleSide, color: 0x7c9a54 });
  const reeds = [];
  for (let i = 0; i < 450; i++) {
    const z = rand(-120, 120);
    const side = rnd() > .5 ? 1 : -1;
    const x = riverXLocal(z) + side * rand(5.5, 8.5);
    if (Math.hypot(x, z) > 140) continue;
    reeds.push({ x, z, y: heightAt(x, z), s: rand(.7, 1.4), sy: rand(1, 1.8), ry: rnd() * TAU, color: new THREE.Color().setHSL(rand(.14, .24), .4, rand(.35, .5)) });
  }
  // lake edge
  for (let i = 0; i < 150; i++) {
    const a = rnd() * TAU, r = 18 + rnd() * 5;
    const x = 58 + Math.cos(a) * r, z = -78 + Math.sin(a) * r;
    reeds.push({ x, z, y: heightAt(x, z), s: rand(.7, 1.3), sy: rand(1, 1.7), ry: rnd() * TAU, color: new THREE.Color().setHSL(rand(.14, .24), .4, rand(.35, .5)) });
  }
  group.add(makeInstance(bladeGeo, reedMat, reeds));

  /* ---------- mushrooms ---------- */
  const mushCap = new THREE.SphereGeometry(.16, 8, 5, 0, TAU, 0, Math.PI / 2);
  const mushStem = new THREE.CylinderGeometry(.04, .06, .22, 5).translate(0, .1, 0);
  const mushGeo = mergeGeometries([mushCap, mushStem]);
  const mushrooms = [];
  for (let i = 0; i < 90; i++) {
    const a = rnd() * TAU, r = Math.sqrt(rnd()) * 110;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (blocked(x, z, -2)) continue;
    mushrooms.push({ x, z, y: heightAt(x, z), s: rand(.7, 1.5), ry: rnd() * TAU, color: new THREE.Color(rnd() > .55 ? '#d75f72' : '#c9a2e8') });
  }
  group.add(makeInstance(mushGeo, toon(0xffffff, { rim: .25, rimColor: 0xffe0e0 }), mushrooms));

  /* ---------- fireflies / petals ---------- */
  const fireflyPositions = [], fireflyData = [];
  for (let i = 0; i < 110; i++) {
    const a = rnd() * TAU, r = Math.sqrt(rnd()) * 100;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    const y = heightAt(x, z) + rand(.6, 2.4);
    fireflyPositions.push(x, y, z);
    fireflyData.push({ baseX: x, baseY: y, baseZ: z, phase: rnd() * TAU, speed: rand(.3, 1) });
  }
  const ffGeo = new THREE.BufferGeometry();
  ffGeo.setAttribute('position', new THREE.Float32BufferAttribute(fireflyPositions, 3));
  const ffMat = new THREE.PointsMaterial({ color: 0xffe99a, size: .13, map: makeSoftTexture(), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: .9, sizeAttenuation: true });
  const ff = new THREE.Points(ffGeo, ffMat);
  ff.renderOrder = 4;
  group.add(ff);

  // floating petals near cherry trees / shrine
  const petals = [];
  const petalGeo = new THREE.PlaneGeometry(.11, .07);
  const petalMat = new THREE.MeshBasicMaterial({ color: 0xffc4d6, transparent: true, opacity: .8, side: THREE.DoubleSide, depthWrite: false });
  const petalMesh = new THREE.InstancedMesh(petalGeo, petalMat, 160);
  const dummy = new THREE.Object3D();
  for (let i = 0; i < 160; i++) {
    petals.push({ x: rand(-30, 40), y: heightAt(0, 0) + rand(.5, 7), z: rand(-40, 50), phase: rand(0, TAU), speed: rand(.3, .9), spin: rand(-2, 2) });
  }
  group.add(petalMesh);
  const tmpColor = new THREE.Color();

  const swayMats = [leafMat, leafMat2];
  function update(time, dt) {
    for (const m of swayMats) if (m.userData.shader) m.userData.shader.uniforms.uTime.value = time;
    // fireflies
    const arr = ffGeo.attributes.position.array;
    for (let i = 0; i < fireflyData.length; i++) {
      const d = fireflyData[i];
      arr[i * 3] = d.baseX + Math.sin(time * d.speed * .7 + d.phase) * 1.4;
      arr[i * 3 + 1] = d.baseY + Math.sin(time * d.speed + d.phase * 2) * .5;
      arr[i * 3 + 2] = d.baseZ + Math.cos(time * d.speed * .55 + d.phase) * 1.4;
    }
    ffGeo.attributes.position.needsUpdate = true;
    ffMat.opacity = .55 + Math.sin(time * 1.2) * .12;
    // petals drift
    for (let i = 0; i < petals.length; i++) {
      const p = petals[i];
      p.y -= dt * p.speed;
      p.x += Math.sin(time * .8 + p.phase) * dt * .35;
      p.z += Math.cos(time * .6 + p.phase) * dt * .25;
      p.phase += dt * p.spin;
      if (p.y < heightAt(p.x, p.z) + .1) { p.y = heightAt(p.x, p.z) + rand(3.5, 8); p.x = rand(-30, 40); p.z = rand(-40, 50); }
      dummy.position.set(p.x, p.y, p.z);
      dummy.rotation.set(p.phase, p.phase * 1.7, p.phase * .6);
      dummy.scale.setScalar(1);
      dummy.updateMatrix();
      petalMesh.setMatrixAt(i, dummy.matrix);
    }
    petalMesh.instanceMatrix.needsUpdate = true;
  }
  update(0, 0);
  return { group, update };
}

