  // weapon rack
  g.add(beam(2.2, .1, .1, M.woodDark, 2.0, 2.0, -1.4));
  for (let i = 0; i < 3; i++) {
    const blade = box(.09, 1.15, .03, M.iron, 1.2 + i * .75, 1.5, -1.4);
    blade.rotation.z = .15; g.add(blade);
    g.add(beam(.26, .06, .06, M.gold, 1.2 + i * .75, .92, -1.4));
