export function caveEntrance() {
  const g = new THREE.Group();
  const rocks = [
    [-4, 1.2, -1, 2.4], [4, 1.0, -1, 2.2], [-2.6, 3.4, -1.5, 1.9], [3.0, 3.6, -1.5, 2.0], [0, 4.8, -2, 2.6],
  ];
