const GLOW = makeGlowTexture('#ffffff');

/* ---------------- anime face texture ---------------- */
function makeFaceTexture() {
  const c = document.createElement('canvas'); c.width = 256; c.height = 256;
  const x = c.getContext('2d');
  x.clearRect(0, 0, 256, 256);
  // brow shadow / lids
  x.strokeStyle = '#3a2c3a'; x.lineWidth = 6; x.lineCap = 'round';
  x.beginPath(); x.moveTo(56, 92); x.quadraticCurveTo(82, 80, 108, 92); x.stroke();
  x.beginPath(); x.moveTo(148, 92); x.quadraticCurveTo(174, 80, 200, 92); x.stroke();
  // eyes (big, anime)
  const eye = (cx, mirror) => {
    x.save(); x.translate(cx, 128); x.scale(mirror, 1);
    x.fillStyle = '#f7f3e8';
    x.beginPath(); x.ellipse(0, 0, 30, 34, 0, 0, 7); x.fill();
    x.fillStyle = '#26203a';
    x.beginPath(); x.ellipse(0, -2, 24, 30, 0, 0, 7); x.fill();
    x.fillStyle = '#45d6d0';
    x.beginPath(); x.ellipse(0, 4, 21, 24, 0, 0, 7); x.fill();
    x.fillStyle = '#1c4c58';
    x.beginPath(); x.ellipse(0, 8, 11, 14, 0, 0, 7); x.fill();
    x.fillStyle = '#ffffff';
    x.beginPath(); x.ellipse(-8, -8, 8, 10, -.2, 0, 7); x.fill();
    x.beginPath(); x.ellipse(8, 10, 4, 5, 0, 0, 7); x.fill();
    x.strokeStyle = '#241d30'; x.lineWidth = 5;
    x.beginPath(); x.ellipse(0, -2, 29, 33, 0, Math.PI * 1.06, Math.PI * 1.94); x.stroke();
    x.beginPath(); x.moveTo(-28, -12); x.lineTo(-30, -26); x.stroke();
    x.restore();
  };
  eye(84, 1); eye(172, -1);
  // nose dot / mouth
  x.fillStyle = 'rgba(150,92,80,.55)';
  x.beginPath(); x.ellipse(128, 172, 2.5, 4, 0, 0, 7); x.fill();
  x.strokeStyle = '#a85a5a'; x.lineWidth = 4;
  x.beginPath(); x.moveTo(116, 196); x.quadraticCurveTo(128, 204, 142, 195); x.stroke();
  // blush
  x.fillStyle = 'rgba(232,110,120,.16)';
  x.beginPath(); x.ellipse(64, 168, 20, 9, 0, 0, 7); x.fill();
  x.beginPath(); x.ellipse(192, 168, 20, 9, 0, 0, 7); x.fill();
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}

const FACE_TEX = makeFaceTexture();

export class Player {
