    addOutline(skull, .012, 0x1a1420);
    // ears
    for (const s of [-1, 1]) { const e = sphere(.045, skin, s * .23, -.01, 0, 6); e.scale.set(.6, 1, .8); head.add(e); }
    // face
    const face = new THREE.Mesh(new THREE.PlaneGeometry(.34, .34), new THREE.MeshBasicMaterial({ map: FACE_TEX, transparent: true, depthWrite: false }));
    face.position.set(0, -.015, .222); head.add(face);
    // hair back
    const hairBack = new THREE.Mesh(new THREE.SphereGeometry(.255, 12, 10, 0, TAU, 0, Math.PI * .72), hair);
    hairBack.position.set(0, .015, -.02); hairBack.scale.set(1.04, 1.12, 1.06); head.add(hairBack);
    addOutline(hairBack, .013, 0x0e0c1a);
    // bangs - cones flattened
    const bangData = [
      [-.15, .13, .18, .5, .12, .2, -.4], [0, .15, .2, .55, .14, .22, 0], [.15, .13, .18, .5, .12, .2, .4],
