86:     } else if (this.q1.state === 'complete' && this.q2.state === 'locked') {
87:       title = 'Ecos de Aetheria';
88:       objectives = [{ text: 'Converse com Mira sobre a ameaça goblin', done: false, highlight: true }];
89:     }
