95:         let text = q.title;
96:         if (id === 'brann') text += ` · Minério ${Math.min(3, this.items.ore)}/3`;
97:         if (id === 'lys') text += ` · Luaflor ${Math.min(4, this.items.flower)}/4`;
98:         if (id === 'tuli') text += ` · Goblins ${Math.min(5, this.tuliKills)}/5`;
99:         sides.push({ text, side: true, done: false });
100:       }
