242:         { text: 'Leve poções. E lembre-se: o gelo o torna lento; o raio interrompe seus rituais. Use o que Aetheria lhe deu.', choices: [{ label: 'Entendido', action: () => {} }] },
243:       ]);
244:       return;
245:     }
246:     this.open('mira', [{ text: 'Aetheria volta a respirar. O cristal brilha no alto do castelo, e os goblins recuaram para as colinas.' }, { text: 'Descanse, viajante. Mas não guarde a espada por muito tempo — o mundo ainda é grande.', choices: [{ label: 'Despedir-se', action: () => {} }] }]);
