401:   /*  INPUT / ACTIONS                                                   */
402:   /* ================================================================== */
403:   get alive() { return !this.dead; }
404:   get pos() { return this.group.position; }
405: 
406:   canAct() {
407:     return !this.dead && !this.action && this.dodgeTime <= 0;
408:   }
409: 
410:   pressAttack() {
411:     if (this.dead) return;
412:     const now = G.time;
413:     this.lastAttackPress = now;
414:     this.attackHeld = true;
415:     this.attackHeldTime = 0;
416:     if (this.charging) return;
417:     if (!this.action || (this.action.name.startsWith('attack') && this.action.t > this.action.dur * .55)) {
418:       if (this.action && this.action.name.startsWith('attack')) { this.queued = true; return; }
419:       this.startAttack();
420:     }
421:   }
422: 
423:   releaseAttack() {
424:     this.attackHeld = false;
425:     if (this.charging) {
426:       this.charging = false;
427:       this.heavyAttack(clamp(.7 + this.chargeT * .9, .8, 2.1));
428:       this.chargeT = 0;
429:       if (G.ui) G.ui.setCharge(0, null);
430:       return;
431:     }
432:     if (this.attackHeldTime < .18 && this.canAct() && !this.queued) {
433:       // no-op; single click already attacked
434:     }
435:   }
436: 
437:   startAttack(index = null) {
438:     if (this.dead) return;
439:     if (!this.action) this.combo = index !== null ? index : (this.combo + 1) % 3;
440:     const names = ['attack1', 'attack2', 'attack3'];
441:     const durations = [.42, .52, .46];
442:     const name = names[this.combo % 3];
443:     this.action = { name, t: 0, dur: durations[this.combo % 3], hitDone: false, combo: this.combo % 3 };
444:     this.queued = false;
445:     this.comboWindow = 1.1;
446:     this.charging = false;
447:     if (G.audio) G.audio.sfx('swing', { pitch: 1 + this.combo * .1 });
448:   }
449: 
450:   heavyAttack(power = 1) {
451:     if (this.dead) return;
452:     this.action = { name: 'heavy', t: 0, dur: .9, hitDone: false, power };
453:     this.combo = 0;
454:     if (G.ui) G.ui.setCharge(0, null);
455:     if (G.audio) G.audio.sfx('heavySwing');
456:   }
457: 
458:   magicDown(element) {
459:     if (this.dead || this.action || this.dodgeTime > 0) return;
460:     if (this.cooldowns[element] > 0) { if (G.audio) G.audio.sfx('error'); return; }
461:     if (this.mp < (element === 'fire' ? 12 : element === 'bolt' ? 22 : 15)) {
462:       if (G.ui) G.ui.toast('Mana insuficiente', 'warn');
463:       if (G.audio) G.audio.sfx('error');
464:       return;
465:     }
466:     if (element === 'fire') {
467:       this.fireCharging = true; this.fireChargeT = 0;
468:       this.effects.magicCircle(this.pos.clone().setY(this.groundYpos()), 'fire', 3.2, 2, this.pos);
469:       if (G.audio) G.audio.sfx('fireCharge');
470:       return;
471:     }
472:     this.cast(element, 1);
473:   }
474: 
475:   magicUp(element) {
476:     if (element !== 'fire' || !this.fireCharging) return;
477:     const power = clamp(1 + this.fireChargeT * .75, 1, 2);
478:     this.fireCharging = false;
479:     if (G.ui) G.ui.setCharge(0, null);
480:     this.cast('fire', power);
481:   }
482: 
483:   cast(element, power = 1) {
484:     if (this.dead) return;
485:     const cost = element === 'fire' ? 12 + Math.round(power * 6) : element === 'bolt' ? 22 : 15;
486:     if (this.mp < cost) { if (G.audio) G.audio.sfx('error'); return; }
487:     this.mp -= cost;
488:     this.cooldowns[element] = element === 'bolt' ? 4.5 : element === 'fire' ? 2.7 : 3.4;
489:     this.action = { name: 'cast', t: 0, dur: element === 'bolt' ? .62 : .55, hitDone: false, element };
490:     this.castElement = element;
491:     this.castPower = power;
492:     this.castResolved = false;
493:     if (G.audio) G.audio.sfx(element === 'bolt' ? 'charge' : element === 'ice' ? 'iceCast' : 'fireCast');
494:     if (G.ui) G.ui.flashSkill(element);
495:     // aim target
496:     let target = this.pickTarget(26, 130 * Math.PI / 180);
497:     if (target) this.faceToward(target.group.position, true);
498:     const aimPos = target ? target.group.position.clone() : this.aimPoint(20);
499:     this.castTarget = target;
500:     this.castAimPos = aimPos;
501:     this.effects.magicCircle(this.pos.clone().setY(this.groundYpos()), element, element === 'bolt' ? 2.6 : 3.4, .9, this.pos);
502:     if (element === 'fire') G.audio && G.audio.sfx('fireCharge');
503:   }
504: 
505:   aimPoint(dist = 18) {
506:     const dir = this.getFacingDir();
507:     return this.pos.clone().addScaledVector(dir, dist).setY(this.groundYpos() + .1);
508:   }
509: 
510:   groundYpos() {
511:     return (G.groundAt ? G.groundAt(this.pos.x, this.pos.z) : heightAt(this.pos.x, this.pos.z));
512:   }
513: 
514:   pickTarget(range = 12, cone = Math.PI) {
515:     if (this.lockedTarget && !this.lockedTarget.dead) return this.lockedTarget;
516:     let best = null, bestScore = 1e9;
517:     const fwd = this.getFacingDir();
518:     for (const e of G.enemies) {
519:       if (e.dead) continue;
520:       const d = e.group.position.distanceTo(this.pos);
521:       if (d > range + (e.radius || 0)) continue;
522:       const to = new THREE.Vector3().subVectors(e.group.position, this.pos).setY(0).normalize();
523:       const ang = Math.acos(clamp(to.dot(fwd), -1, 1));
524:       if (ang > cone / 2 && (!G.target || G.target !== e)) continue;
525:       const score = d * (1 + ang * 1.5);
526:       if (score < bestScore) { bestScore = score; best = e; }
527:     }
528:     return best;
529:   }
530: 
531:   toggleLock() {
532:     if (this.lockedTarget) { this.lockedTarget = null; G.target = null; if (G.ui) G.ui.toast('Alvo liberado'); return; }
533:     let best = null, bd = 26;
534:     for (const e of G.enemies) {
535:       if (e.dead) continue;
536:       const d = e.group.position.distanceTo(this.pos);
537:       if (d < bd) { bd = d; best = e; }
538:     }
539:     if (best) { this.lockedTarget = best; G.target = best; if (G.audio) G.audio.sfx('ui'); if (G.ui) G.ui.toast('Alvo: ' + best.name); }
540:     else if (G.ui) G.ui.toast('Nenhum inimigo por perto');
541:   }
