543:   dodge() {
544:     if (this.dead || this.dodgeCd > 0 || this.stamina < 18) return;
545:     let dir;
546:     const input = this.moveInput();
547:     if (input.lengthSq() > .1) dir = input.normalize();
548:     else dir = this.getFacingDir();
549:     this.dodgeDir.copy(dir);
550:     this.dodgeTime = .3;
551:     this.dodgeCd = 1.15;
552:     this.invuln = Math.max(this.invuln, .38);
553:     this.stamina -= 18;
554:     this.action = null;
555:     this.charging = false;
556:     if (G.ui) G.ui.setCharge(0, null);
557:     if (G.audio) G.audio.sfx('dodge');
558:     this.effects.dust(this.pos.clone().setY(this.groundYpos() + .1), 0xcfd8c0, 14);
559:     this.spawnAfterimage();
560:     if (G.ui) G.ui.flashSkill('dodge');
561:   }
