563:   spawnAfterimage() {
564:     const ghostMat = new THREE.MeshBasicMaterial({ color: 0x8fe8ff, transparent: true, opacity: .28, depthWrite: false, blending: THREE.AdditiveBlending });
565:     const ghost = new THREE.Group();
566:     const body = new THREE.Mesh(new THREE.CapsuleGeometry(.26, .9, 4, 8), ghostMat);
567:     body.position.y = .95;
568:     const head = new THREE.Mesh(new THREE.SphereGeometry(.23, 8, 8), ghostMat);
569:     head.position.y = 1.66;
570:     ghost.add(body, head);
571:     ghost.position.copy(this.pos);
572:     ghost.rotation.y = this.group.rotation.y;
573:     this.scene.add(ghost);
574:     let age = 0;
575:     const tick = () => {
576:       age += .016;
577:       ghostMat.opacity = .28 * (1 - age / .35);
578:       if (age < .35) requestAnimationFrame(tick); else this.scene.remove(ghost);
579:     };
580:     tick();
581:   }
