583:   usePotion() {
584:     if (this.potions <= 0 || this.dead) { if (G.ui) G.ui.toast('Sem poções', 'warn'); if (G.audio) G.audio.sfx('error'); return; }
585:     if (this.hp >= this.maxHp && this.mp >= this.maxMp) { if (G.ui) G.ui.toast('Vida e mana já estão cheias'); return; }
586:     this.potions--;
587:     this.hp = Math.min(this.maxHp, this.hp + 50);
588:     this.mp = Math.min(this.maxMp, this.mp + 30);
589:     this.effects.heal(this.pos.clone().setY(this.groundYpos() + .8));
590:     if (G.audio) G.audio.sfx('heal');
591:     if (G.ui) { G.ui.toast('Poção de Aetheria · +50 vida +30 mana'); G.ui.flashSkill('heal'); G.ui.popHeal(this.pos); }
592:   }
