596:   /* ================================================================== */
597:   takeDamage(amount, sourcePos = null, type = 'physical') {
598:     if (this.dead || this.invuln > 0) return;
599:     if (this.dodgeTime > 0) return;
600:     const dmg = Math.max(1, Math.round(amount));
601:     this.hp -= dmg;
602:     this.invuln = .7;
603:     this.lastHurt = 0;
604:     this.action = null;
605:     this.hitReact = .35;
606:     if (this.charging) { this.charging = false; if (G.ui) G.ui.setCharge(0, null); }
607:     if (G.ui) { G.ui.damage(dmg, this.pos.clone().setY(this.groundYpos() + 1.8), 'player'); G.ui.hurtFlash(); }
608:     if (G.audio) G.audio.sfx('hurt');
609:     this.shake(.4, 5);
610:     if (sourcePos) {
611:       const dir = new THREE.Vector3().subVectors(this.pos, sourcePos).setY(0).normalize();
612:       this.vel.addScaledVector(dir, 4);
613:     }
614:     if (this.hp <= 0) this.die();
615:   }
