709:   update(dt) {
710:     if (this.dead) {
711:       this.respawnTimer -= dt;
712:       this.updateCamera(dt);
713:       this.updateTimers(dt);
714:       if (this.respawnTimer <= 0) this.respawn();
715:       return;
716:     }
717:     this.updateTimers(dt);
718:     this.updateMovement(dt);
719:     this.updateActions(dt);
720:     this.updateAnimation(dt);
721:     this.updateCape(dt);
722:     this.updateCamera(dt);
723:     this.updateFirstPerson(dt);
724:     this.hitReact = Math.max(0, (this.hitReact || 0) - dt);
725:     this.lastHurt += dt;
726:     this.shadow.position.y = 0.04;
727:     this.shadow.material.opacity = this.grounded ? .28 : .12;
728:     // regen
729:     if (this.lastHurt > 7) this.hp = Math.min(this.maxHp, this.hp + 1.6 * dt);
730:     this.mp = Math.min(this.maxMp, this.mp + 2.8 * dt);
731:     if (!this.action && this.dodgeTime <= 0 && !(G.keys['shift'] && this.moveSpeed > 1)) this.stamina = Math.min(this.maxStamina, this.stamina + 20 * dt);
732:     // charge UI
733:     if (this.fireCharging) {
734:       this.fireChargeT = Math.min(1.5, this.fireChargeT + dt);
735:       const k = this.fireChargeT / 1.5;
736:       if (G.ui) G.ui.setCharge(k, 'fire');
737:       if (Math.random() < dt * 14) this.effects.fireCharge(this.handWorldPos(), 1);
738:     } else if (this.charging) {
739:       this.chargeT = Math.min(1.6, this.chargeT + dt);
740:       if (G.ui) G.ui.setCharge(this.chargeT / 1.6, 'sword');
741:       if (Math.random() < dt * 8) this.effects.particles(this.rig.sword.localToWorld(new THREE.Vector3(0, .9, 0)), 0xffe6a0, { count: 1, speed: .8, size: .08, life: .35, gravity: -.5, up: 1 });
742:     }
743:   }
