745:   updateTimers(dt) {
746:     this.invuln = Math.max(0, this.invuln - dt);
747:     this.dodgeCd = Math.max(0, this.dodgeCd - dt);
748:     this.comboWindow = Math.max(0, this.comboWindow - dt);
749:     for (const k in this.cooldowns) this.cooldowns[k] = Math.max(0, this.cooldowns[k] - dt);
750:     if (this.comboWindow <= 0 && !this.action) this.combo = 0;
751:     if (this.shakeT > 0) this.shakeT -= dt;
752:     // held attack -> charge
753:     if (this.attackHeld) {
754:       this.attackHeldTime += dt;
755:       if (!this.charging && this.attackHeldTime > .55 && this.canAct() && !this.fireCharging) {
756:         this.charging = true; this.chargeT = .12;
757:         if (G.audio) G.audio.sfx('charge');
758:       }
759:     }
760:     if (this.charging && !this.attackHeld) { /* released via handler */ }
761:     if (this.charging && this.fireCharging) this.charging = false;
762:   }
