764:   updateMovement(dt) {
765:     const input = this.moveInput();
766:     const runKey = !!(G.keys['shift']);
767:     const busy = this.action || this.charging || this.fireCharging;
768:     let speed = this.moveSpeed;
769:     if (this.dodgeTime > 0) {
770:       this.dodgeTime -= dt;
771:       const t = this.dodgeTime / .3;
772:       this.vel.lerp(this.dodgeDir.clone().multiplyScalar(12 * t), 1 - Math.exp(-dt * 30));
773:       this.group.position.addScaledVector(this.vel, dt);
774:       this.faceToward(this.pos.clone().add(this.dodgeDir), false);
775:     } else {
776:       let baseSpeed = runKey && this.stamina > 1 ? 7.2 : 4.2;
777:       if (this.grounded && surfaceAt(this.pos.x, this.pos.z) === 'water') baseSpeed *= .55;
778:       if (busy) baseSpeed *= .32;
779:       if (this.firstPerson) baseSpeed *= .96;
780:       const forwardYaw = this.firstPerson ? this.viewYaw : this.camAngle + Math.PI;
781:       const camForward = new THREE.Vector3(Math.sin(forwardYaw), 0, Math.cos(forwardYaw));
782:       const camRight = new THREE.Vector3(camForward.z, 0, -camForward.x);
783:       const world = new THREE.Vector3();
784:       world.addScaledVector(camForward, input.z);
785:       world.addScaledVector(camRight, input.x);
786:       if (world.lengthSq() > 1) world.normalize();
787:       // locked target: strafe, face target
788:       const target = this.lockedTarget && !this.lockedTarget.dead ? this.lockedTarget : null;
789:       if (target) this.faceToward(target.group.position, false);
790:       else if (world.lengthSq() > .01) {
791:         const yaw = Math.atan2(world.x, world.z);
792:         this.facing = yaw;
793:       }
794:       if (!this.firstPerson) {
795:         if (this.action && this.action.name.startsWith('attack')) { /* keep facing */ }
796:         else {
797:           let diff = angleDiff(this.facing, this.group.rotation.y);
798:           this.group.rotation.y += diff * (1 - Math.exp(-dt * (this.dodgeTime > 0 ? 18 : 12)));
799:         }
800:       } else {
801:         this.group.rotation.y = this.viewYaw;
802:       }
803:       const targetVel = world.multiplyScalar(baseSpeed);
804:       this.vel.x = damp(this.vel.x, targetVel.x, 12, dt);
805:       this.vel.z = damp(this.vel.z, targetVel.z, 12, dt);
806:       if (runKey && this.grounded && input.lengthSq() > .1) this.stamina = Math.max(0, this.stamina - 14 * dt);
807:       if (this.action && this.action.name === 'attack3' && this.action.t < this.action.dur * .5) {
808:         this.group.position.addScaledVector(this.getFacingDir(), dt * 3.4);
809:       }
810:       this.group.position.x += this.vel.x * dt;
811:       this.group.position.z += this.vel.z * dt;
812:       this.moveSpeed = Math.hypot(this.vel.x, this.vel.z) * (input.lengthSq() > .1 ? 1 : 0);
813:       // footsteps
814:       if (this.grounded && this.moveSpeed > .7) {
815:         this.walkPhase += dt * (this.moveSpeed > 5.5 ? 11.5 : 8.2);
816:         this.stepTimer -= dt;
817:         if (this.stepTimer <= 0) {
818:           this.stepTimer = this.moveSpeed > 5.5 ? .27 : .4;
819:           const surface = surfaceAt(this.pos.x, this.pos.z);
820:           if (G.audio) G.audio.sfx(surface === 'water' ? 'stepWater' : surface === 'stone' ? 'stepStone' : 'stepGrass');
821:           if (surface === 'water' && Math.random() < .4) this.effects.dust(this.pos.clone().setY(this.groundYpos() + .1), 0xd8f4ff, 5);
822:           else this.effects.dust(this.pos.clone().setY(this.groundYpos() + .05), 0xb8a882, 2);
823:         }
824:       } else this.walkPhase += dt * .8;
825:       // jump / gravity
826:       if (G.keys[' '] && this.grounded && this.canAct()) {
827:         this.vy = 7.4; this.grounded = false;
828:         if (G.audio) G.audio.sfx('jump');
829:       }
830:       let groundY = (G.groundAt ? G.groundAt(this.pos.x, this.pos.z) : heightAt(this.pos.x, this.pos.z));
831:       if (isWaterAt(this.pos.x, this.pos.z)) groundY = Math.max(groundY, WATER_LEVEL - .72);
832:       if (!this.grounded) {
833:         this.vy -= 22 * dt;
834:         this.group.position.y += this.vy * dt;
835:         if (this.group.position.y <= groundY) {
836:           this.group.position.y = groundY; this.vy = 0; this.grounded = true;
837:           if (G.audio) G.audio.sfx('land');
838:           this.effects.dust(this.pos.clone().setY(groundY + .1), 0xb8a882, 8);
839:         }
840:       } else {
841:         this.group.position.y = damp(this.group.position.y, groundY, 18, dt);
842:       }
843:       if (!this.firstPerson && input.lengthSq() > .1 && input.z > .3 && Math.abs(input.x) < .5 && !this.lockedTarget && G.time - this.lastDrag > 2) {
844:         this.camAngle = dampAngle(this.camAngle, this.group.rotation.y + Math.PI, .9, dt);
845:       }
846:       // collisions
847:       this.resolveCollisions();
848:     }
849:     // world bounds
850:     const r = Math.hypot(this.pos.x, this.pos.z);
851:     if (r > 148) { this.pos.x *= 148 / r; this.pos.z *= 148 / r; }
852:   }
853: 
854:   resolveCollisions() {
855:     const cols = G.colliders || [];
856:     for (const c of cols) {
857:       const dx = this.pos.x - c.x, dz = this.pos.z - c.z;
858:       const d = Math.hypot(dx, dz);
859:       const rr = c.r + .35;
860:       if (d < rr && d > .001) {
861:         const push = (rr - d);
862:         this.pos.x += dx / d * push;
863:         this.pos.z += dz / d * push;
864:       }
865:     }
866:   }
867: 
868:   handWorldPos() {
869:     const p = new THREE.Vector3();
870:     if (this.firstPerson) {
871:       this.fpLArm.getWorldPosition(p);
872:       p.add(new THREE.Vector3(0, 0, -.5));
873:     } else {
874:       this.rig.armL.hand.getWorldPosition(p);
875:       p.y += .1;
876:     }
877:     return p;
