880:   updateActions(dt) {
881:     // queue follow-up combo
882:     if (!this.action && this.queued && this.comboWindow > 0) {
883:       this.queued = false;
884:       this.startAttack();
885:     }
886:     if (!this.action) return;
887:     const a = this.action;
888:     a.t += dt;
889:     const t = a.t / a.dur;
890:     if (a.name.startsWith('attack') && !a.hitDone && t > .34) {
891:       a.hitDone = true;
892:       this.resolveSwordHit(a);
893:     }
894:     if (a.name === 'heavy') {
895:       if (t > .32 && !a.hitDone) {
896:         a.hitDone = true;
897:         this.resolveHeavyHit(a.power);
898:       }
899:     }
900:     if (a.name === 'cast') {
901:       if (!this.castResolved && t > (a.element === 'bolt' ? .55 : .5)) {
902:         this.castResolved = true;
903:         this.resolveCast(this.castElement, this.castPower);
904:       }
905:     }
906:     if (a.t >= a.dur) {
907:       this.action = null;
908:       this.castElement = null;
909:     }
910:   }
