912:   /* ---------------- damage resolution ---------------- */
913:   swordBase() { return 9 + this.swordLevel * 4.5 + this.level * 1.6; }
914:   magicBase() { return 16 + this.magicLevel * 6 + this.level * 2; }
915: 
916:   rollCrit() { return Math.random() < this.critChance; }
917: 
918:   resolveSwordHit(a) {
919:     const combo = a.combo || 0;
920:     const range = combo === 2 ? 3.4 : 2.9;
921:     const arc = combo === 1 ? 2.8 : 2.4;
922:     const mult = [1, 1.12, 1.35][combo];
923:     const fwd = this.getFacingDir();
924:     const center = this.pos.clone().addScaledVector(fwd, 1.2).setY(this.groundYpos() + 1.1);
925:     // slash vfx
926:     if (combo === 1) this.effects.slash(center, this.group.rotation.y + Math.PI / 2, { color: 0xfff0c0, vertical: true, radius: 2.5, flip: true });
927:     else if (combo === 2) this.effects.slash(center, this.group.rotation.y, { color: 0xd8f4ff, radius: 2.2, tilt: .05 });
928:     else this.effects.slash(center, this.group.rotation.y, { color: 0xfff0c0, radius: 2.7 });
929:     if (G.audio) G.audio.sfx('swing', { pitch: 1 + combo * .12 });
930:     let hitAny = false;
931:     for (const e of G.enemies) {
932:       if (e.dead) continue;
933:       const d = e.group.position.distanceTo(this.pos);
934:       if (d > range + (e.radius || 0)) continue;
935:       const to = new THREE.Vector3().subVectors(e.group.position, this.pos).setY(0).normalize();
936:       const ang = Math.abs(angleDiff(Math.atan2(to.x, to.z), this.group.rotation.y));
937:       if (ang > arc / 2) continue;
938:       const crit = this.rollCrit();
939:       const dmg = Math.round(this.swordBase() * mult * (crit ? 1.7 : 1) * rand(.92, 1.08));
940:       e.takeDamage(dmg, {
941:         type: 'physical', crit, from: this.pos,
942:         knockback: combo === 2 ? 3.5 : 1.8,
943:         effect: (pos) => this.effects.hitSpark(pos, 0xfff0c0, crit),
944:       });
945:       hitAny = true;
946:       if (G.hitStop !== undefined) G.hitStop = Math.max(G.hitStop || 0, crit ? .08 : .045);
947:       this.shake(.18, crit ? 4 : 2);
948:       if (G.audio) G.audio.sfx(crit ? 'crit' : 'hit');
949:     }
950:     if (!hitAny) {
951:       // whiff air particle
952:       this.effects.particles(center, 0xfff4d0, { count: 4, speed: .6, size: .06, life: .25, gravity: 0, additive: true });
953:     }
954:   }
955: 
956:   resolveHeavyHit(power) {
957:     const center = this.pos.clone().setY(this.groundYpos() + .7);
958:     this.effects.slash(center, this.group.rotation.y, { color: 0xffe6a0, radius: 3.8, tilt: .02, life: .35 });
959:     this.effects.shockwave(this.pos.clone().setY(this.groundYpos() + .1), 0xffd27a, 4.6, .55);
960:     this.effects.dust(this.pos.clone().setY(this.groundYpos() + .1), 0xd8c49a, 22);
961:     this.shake(.35, 5);
962:     let hit = 0;
963:     for (const e of G.enemies) {
964:       if (e.dead) continue;
965:       const d = e.group.position.distanceTo(this.pos);
966:       if (d > 3.8 + (e.radius || 0)) continue;
967:       const crit = this.rollCrit();
968:       const dmg = Math.round(this.swordBase() * 2.1 * power * (crit ? 1.6 : 1));
969:       e.takeDamage(dmg, {
970:         type: 'physical', crit, from: this.pos, knockback: 8,
971:         effect: (pos) => this.effects.hitSpark(pos, 0xffd27a, true),
972:       });
973:       hit++;
974:     }
975:     if (hit) { G.hitStop = Math.max(G.hitStop || 0, .1); if (G.audio) G.audio.sfx('crit'); }
976:     if (G.ui) G.ui.flashSkill('sword');
977:   }
978: 
979:   resolveCast(element, power) {
980:     const target = this.castTarget && !this.castTarget.dead ? this.castTarget : null;
981:     const targetPosFn = () => target ? target.group.position.clone() : this.castAimPos.clone();
982:     const from = this.handWorldPos();
983:     if (element === 'fire') {
984:       this.effects.fireball(from, targetPosFn, {
985:         color: 0xff8a3a, scale: .9 + power * .5, speed: 20,
986:         onHit: (p) => {
987:           const radius = 2.6 + power * .5;
988:           if (G.audio) G.audio.sfx('explosion');
989:           if (G.player) G.player.shake(.3, 4);
990:           for (const e of G.enemies) {
991:             if (e.dead) continue;
992:             const d = e.group.position.distanceTo(p);
993:             if (d < radius + (e.radius || 0)) {
994:               const crit = this.rollCrit();
995:               const falloff = 1 - clamp(d / (radius + 1.5), 0, .55);
996:               const dmg = Math.round(this.magicBase() * 1.35 * power * falloff * (crit ? 1.7 : 1));
997:               e.takeDamage(dmg, { type: 'fire', crit, from: this.pos, knockback: 2.5, burn: 2, effect: (ep) => this.effects.hitSpark(ep, 0xffa04a, crit) });
998:             }
999:           }
1000:         },
1001:       });
1002:       this.effects.fireCharge(from, .25);
1003:     } else if (element === 'bolt') {
1004:       const p = targetPosFn();
1005:       p.y = (G.groundAt ? G.groundAt(p.x, p.z) : heightAt(p.x, p.z));
1006:       // delayed strike
1007:       this.pendingBolt = { t: .22, pos: p, power };
1008:       this.effects.magicCircle(p.clone().setY(p.y + .06), 'bolt', 4, .5);
1009:     } else if (element === 'ice') {
1010:       this.effects.iceShard(from, targetPosFn, {
1011:         onHit: (p) => {
1012:           for (const e of G.enemies) {
1013:             if (e.dead) continue;
1014:             const d = e.group.position.distanceTo(p);
1015:             if (d < 2.4 + (e.radius || 0)) {
1016:               const crit = this.rollCrit();
1017:               const dmg = Math.round(this.magicBase() * 1.05 * (crit ? 1.7 : 1));
1018:               e.takeDamage(dmg, { type: 'ice', crit, from: this.pos, knockback: 1, freeze: 3, effect: (ep) => this.effects.hitSpark(ep, 0x9ff0ff, crit) });
1019:               if (G.audio) G.audio.sfx('freeze');
1020:             }
1021:           }
1022:         },
1023:       });
1024:     }
1025:   }
1026: 
1027:   updatePending(dt) {
1028:     if (this.pendingBolt) {
1029:       this.pendingBolt.t -= dt;
1030:       if (this.pendingBolt.t <= 0) {
1031:         const { pos, power } = this.pendingBolt;
1032:         this.pendingBolt = null;
1033:         this.effects.lightning(pos, {});
1034:         const radius = 3.6;
1035:         for (const e of G.enemies) {
1036:           if (e.dead) continue;
1037:           const d = e.group.position.distanceTo(pos);
1038:           if (d < radius + (e.radius || 0)) {
1039:             const crit = this.rollCrit();
1040:             const dmg = Math.round(this.magicBase() * 1.6 * power * (crit ? 1.8 : 1));
1041:             e.takeDamage(dmg, { type: 'bolt', crit, from: this.pos, knockback: 4, effect: (ep) => this.effects.hitSpark(ep, 0xffe86a, crit) });
1042:           }
1043:         }
1044:         G.hitStop = Math.max(G.hitStop || 0, .07);
1045:       }
1046:     }
1047:   }
1048: 
1049:   /* ---------------- animation ---------------- */
1050:   updateAnimation(dt) {
1051:     const rig = this.rig;
1052:     const speedFactor = clamp(this.moveSpeed / 7.2, 0, 1);
1053:     const phase = this.walkPhase;
1054:     const t = G.time;
1055:     const idle = Math.sin(t * 1.9) * .5 + .5;
1056:     const a = this.action;
