369:   update(dt) {
370:     if (this.dead) { this.updateDeath(dt); return; }
371:     this.updateFlash(dt);
372:     this.frozen = this.freezeT > 0;
373:     if (this.freezeT > 0) this.freezeT -= dt;
374:     if (this.burnT > 0) {
375:       this.burnT -= dt;
376:       this.burnAcc = (this.burnAcc || 0) + dt;
377:       if (this.burnAcc > .5) { this.burnAcc = 0; this.applyDamage(this.burnDmg, { type: 'fire', silent: false }); }
378:     }
379:     if (!this.player || this.player.dead) { this.aggro = false; }
380:     const p = this.player.pos;
381:     const dist = this.group.position.distanceTo(p);
382:     const playerAlive = this.player && !this.player.dead;
383: 
384:     if (!this.aggro) {
385:       if (playerAlive && dist < this.cfg.aggro) this.alertNow();
386:       else { this.updateWander(dt); this.updateRig(dt); this.updateBar(); return; }
387:     }
388:     if (!playerAlive || dist > 32) {
389:       this.aggro = false;
390:       if (this.isBoss) { G.ui && G.ui.hideBoss(); }
391:       this.attack = null;
392:       this.updateWander(dt); this.updateRig(dt); this.updateBar(); return;
393:     }
394:     if (this.frozen) {
395:       this.attack = null;
396:       this.updateRig(dt); this.updateBar(); this.updateFacing(dt, false); return;
397:     }
398:     this.alertT = Math.max(0, this.alertT - dt);
399:     this.alert.visible = this.alertT > 0;
400: 
401:     // boss phase checks
402:     if (this.isBoss) this.checkBossPhases();
403: 
404:     this.updateFacing(dt, true);
405:     if (this.attack) { this.updateAttack(dt); this.updateRig(dt, true); this.updateBar(); return; }
406: 
407:     this.cd -= dt;
408:     const toward = new THREE.Vector3().subVectors(p, this.group.position).setY(0);
409:     const flatDist = toward.length();
410:     let move = new THREE.Vector3();
411:     const speed = this.cfg.speed * (this.enraged ? 1.28 : 1);
412:     const u = this.cfg.uniform;
413: 
414:     if (u === 'archer') {
415:       if (flatDist < 7) move.copy(toward).normalize().multiplyScalar(-1);
416:       else if (flatDist > 13) move.copy(toward).normalize();
