/* Shared game namespace + tiny helpers to avoid circular imports. */
export const G = {
  scene: null, camera: null, renderer: null, clock: null,
  player: null, world: null, effects: null, ui: null, audio: null,
  enemies: [], npcs: [], interactables: [], pickups: [], projectiles: [],
  keys: {}, mouse: { left: false, right: false, x: 0, y: 0, dx: 0, dy: 0 },
  time: 0, dt: 0, paused: false, running: false, over: false,
  stats: { kills: 0, gold: 120, deaths: 0, startTime: 0, goblinsKilled: 0, shards: 0 },
  settings: { muted: false, quality: 2 },
  cameraMode: 'third',
  target: null,
  zone: 'Vila de Brisa',
  flags: {},
  debug: false,
};
export const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
export function dist2d(a, b) { return Math.hypot(a.x - b.x, a.z - b.z); }
export function angleTo(a, b) { return Math.atan2(b.x - a.x, b.z - a.z); }
export function angleDiff(a, b) { let d = a - b; while (d > Math.PI) d -= Math.PI * 2; while (d < -Math.PI) d += Math.PI * 2; return d; }
export function forwardOf(obj) { return { x: Math.sin(obj.rotation.y), z: Math.cos(obj.rotation.y) }; }
import * as THREE from 'three';
import { G } from '../core/state.js';
import {
  toon, box, cyl, cone, sphere, plane, glowSprite, makeGlowTexture,
  clamp, rand, TAU, makeRuneTexture
} from '../core/utils.js';
import {
  heightAt, isWater, WATER_LEVEL, buildTerrain, buildWater, buildRoads, riverX
} from './terrain.js';
import { buildSky } from './sky.js';
import { buildVegetation } from './props.js';
import {
  house, tavern, smithy, alchemist, shopHouse, temple, barracks, marketStall,
  fountain, well, bench, lamp, fence, crates, bannerPole, cart, clothesline,
  goblinTent, goblinCampProps, ruinsSite, ruinAltar, shrineSite, caveEntrance,
  mineEntrance, bridge, windmill, farmPlot, scarecrow, waterfallSite, signpost,
  abandonedHut, wizardTower, castleGate, castleKeep, castleWalls, campfire,
  stoneLantern, goblinTotem, goblinCage
} from './structures.js';
import { NPC } from './npcs.js';
import { Enemy } from '../entities/enemies.js';

const GLOW = makeGlowTexture('#ffffff');

/* ================================================================== */
/*  World                                                             */
/* ================================================================== */
export class World {
  constructor(scene, effects, quality = 2) {
    this.scene = scene;
    this.effects = effects;
    this.quality = quality;
    this.colliders = G.colliders = [];
    this.exclusions = [];
    this.npcs = {};
    this.npcList = [];
    this.altars = {};
    this.pickups = [];
    this.interactables = G.interactables = [];
    this.mapPOIs = [];
    this.waypoint = null;
    this.zone = '';
    this.markerTimer = 0;
    this.fireLights = [];
    this.animated = [];

    this.altarPositions = {
      shrine: { x: 68, z: -6 },
      ruins: { x: 52, z: -47 },
      cave: { x: -76, z: 11 },
    };

    this.buildBase();
    this.buildVillage();
    this.buildLandmarks();
    this.buildVegetation();
    this.buildNPCs();
    this.buildPickups();
    this.spawnEnemies();
    this.buildBeacon();

    G.world = this;
    G.npcs = this.npcList;
    G.enemies = this.enemies;
    G.zone = 'Vila de Brisa';
    this.refreshMarkers();
  }

  /* ------------------------------------------------------------------ */
  /*  Base terrain                                                      */
  /* ------------------------------------------------------------------ */
  buildBase() {
    this.sky = buildSky(this.scene, this.quality);
    this.terrain = buildTerrain(this.scene, this.quality);
    this.water = buildWater(this.scene);
    this.roads = buildRoads(this.scene);
    this.bridgePos = { x: riverX(-60), z: -60 };
  }

  addExclusion(x, z, r) { this.exclusions.push({ x, z, r }); }
  addCollider(x, z, r) {
    for (const c of this.colliders) {
      if (Math.hypot(c.x - x, c.z - z) < Math.max(3, r) && Math.abs(c.r - r) < .2) return;
    }
    this.colliders.push({ x, z, r });
  }

  place(obj, x, z, rot = 0, y = null) {
    obj.position.set(x, y === null ? heightAt(x, z) : y, z);
    obj.rotation.y = rot;
    this.scene.add(obj);
    return obj;
  }

  buildVillage() {
    const S = this.scene;

    // ---- central plaza ----
    const f = fountain();
    this.place(f, 6, 28);
    this.fountain = f;
    this.addCollider(6, 28, 3.4);
    this.addExclusion(6, 28, 7);
    this.mapPOIs.push({ x: 6, z: 28, name: 'Praça do Cristal', icon: '✦', kind: 'town' });

    // ---- main buildings ----
    const tavernG = tavern({ rot: 0 });
    this.place(tavernG, -13, 38);
    this.addCollider(-13, 38, 4.3); this.addExclusion(-13, 38, 7.4);
    this.mapPOIs.push({ x: -13, z: 38, name: 'Taverna O Cervo Errante', icon: '🍺', kind: 'town' });

    const smithyG = smithy({ rot: 0 });
    this.place(smithyG, 14, 37);
    this.addCollider(14, 37, 4.0); this.addExclusion(14, 37, 7);
    this.mapPOIs.push({ x: 14, z: 37, name: 'Forja de Brann', icon: '⚒', kind: 'town' });
    const forgeLight = new THREE.PointLight(0xff8a3a, 7, 12, 2);
    forgeLight.position.set(13, heightAt(14, 37) + 2.4, 36);
    S.add(forgeLight);
    this.fireLights.push({ light: forgeLight, base: 7, phase: 0 });

import * as THREE from 'three';
import { G, isTouch } from '../core/state.js';
import { makePortrait, projectToScreen, clamp } from '../core/utils.js';
import { ROADS, riverX, heightAt } from '../world/terrain.js';

const $ = id => document.getElementById(id);

const PLAYER_PORTRAIT_CFG = {
  hair: '#2b2848', hair2: '#4a4478', eye: '#65e6d8',
  cloth: '#254a5f', cloth2: '#d8b45c', skin: '#f6c9a2',
  accessory: 'circlet', bg1: '#1d4250', bg2: '#08121c',
};

const COOLDOWN_MAX = { fire: 2.7, bolt: 4.5, ice: 3.4, dodge: 1.15 };
const DIRS = [
  [0, 'N'], [45, 'NE'], [90, 'L'], [135, 'SE'], [180, 'S'], [225, 'SO'], [270, 'O'], [315, 'NO'], [360, 'N'],
];

/* ================================================================== */
/*  Interface                                                         */
/* ================================================================== */
export class UI {
  constructor() {
    this.el = {};
    for (const id of [
      'hud', 'portrait', 'levelBadge', 'hpFill', 'hpText', 'mpFill', 'mpText', 'stFill',
      'compassBar', 'zoneTitle', 'minimap', 'goldText', 'potionText', 'questTitle',
      'questObjectives', 'bossBar', 'bossName', 'bossPhase', 'bossFill', 'bossGhost',
      'enemyBars', 'skillbar', 'interactPrompt', 'interactText', 'lockHint', 'toast',
      'subtitle', 'crosshair', 'damageLayer', 'dialogue', 'dlgPortrait', 'dlgName',
      'dlgText', 'dlgChoices', 'dlgNext', 'shopPanel', 'shopTitle', 'shopGold',
      'shopItems', 'shopFoot', 'mapPanel', 'bigmap', 'pausePanel', 'helpText',
      'pausePanel', 'ending', 'endingTitle', 'endingText', 'endingStats', 'mobile',
      'loading', 'loadFill', 'loadTip', 'start', 'startBtn', 'resumeBtn', 'helpBtn',
      'muteBtn', 'restartBtn', 'againBtn', 'continueBtn', 'flash', 'grade',
    ]) this.el[id] = $(id);
    this.el.dlgNext = document.querySelector('.dlg-next');

    this.dialogueOpen = false;
