    sp.position.set(sx, sy, sz); sp.rotation.x = rx; head.add(sp);
  }
  // circlet
  const circlet = new THREE.Mesh(new THREE.TorusGeometry(.205, .016, 5, 16, Math.PI * 1.1), gold);
  circlet.rotation.set(Math.PI / 2, 0, Math.PI * .45); circlet.position.y = .11; head.add(circlet);
  const gem = new THREE.Mesh(new THREE.OctahedronGeometry(.035, 0), new THREE.MeshBasicMaterial({ color: 0x8ff8ff }));
  gem.position.set(0, .16, .21); head.add(gem);
  this.addHeadGlow(gem);

  // arms
  const makeArm = (side) => {
    const shoulder = new THREE.Group();
  const capeGeo = new THREE.PlaneGeometry(.76, 1.2, 5, 10);
  capeGeo.translate(0, -.6, 0);
  const cape = new THREE.Mesh(capeGeo, capeMat);
  cape.position.set(0, .5, -.16);
  torso.add(cape);
  rig.cape = cape;
  rig.capeBase = capeGeo.attributes.position.array.slice();
  const capeTrim = new THREE.Mesh(new THREE.PlaneGeometry(.8, .05), gold);
  capeTrim.position.set(0, -.02, -.005); cape.add(capeTrim);
  // back banner-like cloth pieces
  for (const s of [-1, 1]) {
    const strip = new THREE.Mesh(new THREE.PlaneGeometry(.12, .5), capeMat);
    strip.position.set(s * .3, .3, -.2); strip.rotation.z = s * .12; torso.add(strip);
    rig['strip' + s] = strip;
  }

  // soft blob shadow
  const shadowGeo = new THREE.CircleGeometry(.6, 18);
  const shadowMat = new THREE.MeshBasicMaterial({ color: 0x0a1a12, transparent: true, opacity: .28, depthWrite: false });
  this.shadow = new THREE.Mesh(shadowGeo, shadowMat);
  this.shadow.rotation.x = -Math.PI / 2;
  this.group.add(this.shadow);
  this.shadow.position.y = .04;

  this.group.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = false; } });
  this.shadow.castShadow = false;
  this.chest = chest;
}
buildFirstPerson() {
  const fp = this.fp = new THREE.Group();
  fp.visible = false;
  G.camera.add(fp);
  const skin = toon(0xf6c9a2, { rim: .2, rimColor: 0xffe8d0 });
  const sleeve = toon(0x254a5f, { rim: .2, rimColor: 0x9fe4ff });
  const glove = toon(0x49301f, { rim: .16, rimColor: 0xffc890 });
  const steel = toon(0xc8d6e4, { rim: .5, rimColor: 0xffffff, emissive: 0x1a2430, emissiveIntensity: .35 });
  const gold = toon(0xe0b25a, { rim: .5, rimColor: 0xfff4c0 });

  const rArm = new THREE.Group();
  rArm.position.set(.3, -.34, -.5); rArm.rotation.set(.9, -.15, -.35); fp.add(rArm);
  const rFore = cyl(.055, .07, .44, 7, sleeve, 0, 0, -.22); rFore.rotation.x = Math.PI / 2; rArm.add(rFore);
  const rHand = sphere(.075, glove, 0, -.02, -.44, 8); rHand.scale.set(1, .9, 1.1); rArm.add(rHand);
  const sword = new THREE.Group();
  sword.position.set(0, .02, -.5);
  sword.rotation.set(-1.15, .25, -.55);
  rArm.add(sword);
  sword.add(box(.055, .8, .016, steel, 0, .4, 0));
  sword.add(box(.24, .04, .05, gold, 0, .02, 0));
  sword.add(box(.03, .16, .03, glove, 0, -.08, 0));
  const tip = new THREE.Mesh(new THREE.ConeGeometry(.04, .14, 4), steel); tip.position.y = .87; sword.add(tip);
  const gem = new THREE.Mesh(new THREE.OctahedronGeometry(.03, 0), new THREE.MeshBasicMaterial({ color: 0x8ff8ff })); gem.position.set(0, .03, .03); sword.add(gem);
  this.fpSword = sword;
  this.fpRArm = rArm;

  const lArm = new THREE.Group();
  lArm.position.set(-.3, -.36, -.46); lArm.rotation.set(.85, .25, .3); fp.add(lArm);
  const lFore = cyl(.05, .065, .4, 7, sleeve, 0, 0, -.2); lFore.rotation.x = Math.PI / 2; lArm.add(lFore);
  const lHand = sphere(.07, skin, 0, 0, -.4, 8); lArm.add(lHand);
  const book = new THREE.Group(); book.position.set(0, .06, -.47); book.rotation.set(-.4, -.2, .3); lArm.add(book);
  book.add(box(.18, .04, .14, glove, 0, 0, 0));
  book.add(box(.16, .035, .125, toon(0xe8dcc0), 0, .02, 0));
  const bookRune = new THREE.Mesh(new THREE.CircleGeometry(.045, 12), new THREE.MeshBasicMaterial({ color: 0x8ff8ff }));
  bookRune.rotation.x = -Math.PI / 2; bookRune.position.y = .045; book.add(bookRune);
  const glow = glowSprite(0x7ff0ff, .35, GLOW); glow.material.opacity = .3; glow.position.y = .08; book.add(glow);
  this.fpBookGlow = glow;
  this.fpLArm = lArm;
  const handGlow = glowSprite(0xffb066, .01, GLOW); handGlow.material.opacity = 0; handGlow.position.set(0, 0, -.55); lArm.add(handGlow);
  this.fpHandGlow = handGlow;

  // gauntlet-mounted lantern for mood? small glow to light hands visually
  fp.traverse(o => { if (o.isMesh) { o.castShadow = false; o.receiveShadow = false; } });
}

/* ================================================================== */
/*  INPUT / ACTIONS                                                   */
/* ================================================================== */
get alive() { return !this.dead; }
get pos() { return this.group.position; }

