253: /* ------------------------------------------------------------------ */
254: /*  Input                                                             */
255: /* ------------------------------------------------------------------ */
256: function setupInput() {
257:   const canvas = renderer.domElement;
258: 
259:   const normalizeKey = e => (e.key || '').toLowerCase();
260:   const blockedKeys = new Set([' ', 'tab', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright']);
261: 
262:   window.addEventListener('keydown', e => {
263:     const k = normalizeKey(e);
264:     if (blockedKeys.has(k)) e.preventDefault();
265:     if (e.repeat) {
266:       if (k === 'shift' || k === 'w' || k === 'a' || k === 's' || k === 'd') G.keys[k] = true;
267:       return;
268:     }
269: 
270:     // menu / modals
271:     if (ui.dialogueOpen) {
272:       if (k === 'e' || k === 'enter' || k === ' ') ui.advanceDialogue();
273:       if (k === 'escape') ui.hideDialogue();
274:       return;
275:     }
276:     if (ui.activePanel) {
277:       if (k === 'escape' || k === 'p') ui.closePanel();
278:       if (k === 'm' && ui.activePanel === 'mapPanel') ui.closePanel();
279:       return;
280:     }
281:     if (!G.running) {
282:       if (k === 'enter' && !G.over) startGame();
283:       return;
284:     }
285:     if (G.over) return;
286: 
287:     G.keys[k] = true;
288: 
289:     if (k === 'escape') {
290:       if (document.pointerLockElement) document.exitPointerLock();
291:       else { ui.openPause(); G.paused = true; }
292:       return;
293:     }
294:     if (k === 'p') {
295:       ui.openPause();
296:       G.paused = true;
297:       return;
298:     }
299:     if (k === 'm') { ui.toggleMap(); return; }
300:     if (k === 'v') {
301:       player.setFirstPerson(!player.firstPerson);
302:       if (player.firstPerson) {
303:         ensurePointerLockIfFirstPerson();
304:         ui.toast('Primeira pessoa · V alterna', 'good');
305:       } else {
306:         try { document.exitPointerLock && document.exitPointerLock(); } catch (_) { /* noop */ }
307:         ui.toast('Terceira pessoa · arraste com o botão direito para girar');
308:       }
309:       return;
310:     }
311:     if (k === 'q') { player.dodge(); return; }
312:     if (k === 'h') { player.usePotion(); return; }
313:     if (k === 'e') { interact(); return; }
314:     if (k === 'tab') { player.toggleLock(); return; }
315:     if (k === '1') { player.magicDown('fire'); return; }
316:     if (k === '2') { player.magicDown('bolt'); return; }
317:     if (k === '3') { player.magicDown('ice'); return; }
318:   });
319: 
320:   window.addEventListener('keyup', e => {
321:     const k = normalizeKey(e);
322:     G.keys[k] = false;
323:     if (k === '1') player && player.magicUp('fire');
324:   });
325: 
326:   window.addEventListener('blur', () => { G.keys = {}; G.mouse.left = false; });
327: 
328:   // ---- pointer / camera ----
329:   canvas.addEventListener('contextmenu', e => e.preventDefault());
330: 
331:   let dragging = false;
332:   let lastX = 0, lastY = 0;
333: 
334:   canvas.addEventListener('pointerdown', e => {
335:     if (!G.running || G.over) return;
336:     if (ui.modalOpen) return;
337:     if (e.pointerType === 'touch') {
338:       dragging = true; lastX = e.clientX; lastY = e.clientY;
339:       canvas.setPointerCapture && canvas.setPointerCapture(e.pointerId);
340:       return;
341:     }
342:     if (e.button === 0) {
343:       if (player.firstPerson && document.pointerLockElement !== canvas && canvas.requestPointerLock) {
344:         canvas.requestPointerLock();
345:       }
346:       player.pressAttack();
347:     } else if (e.button === 2) {
348:       dragging = true; lastX = e.clientX; lastY = e.clientY;
349:       canvas.setPointerCapture && canvas.setPointerCapture(e.pointerId);
350:     }
351:   });
352: 
353:   const endPointer = e => {
354:     if (e.pointerType !== 'touch' && e.button === 0 && G.running) player.releaseAttack();
355:     if (e.pointerType === 'touch' || e.button === 2) dragging = false;
356:   };
357:   canvas.addEventListener('pointerup', endPointer);
358:   canvas.addEventListener('pointercancel', e => { dragging = false; player.releaseAttack(); });
359: 
360:   document.addEventListener('mousemove', e => {
361:     if (!G.running || G.over || ui.modalOpen) return;
362:     if (document.pointerLockElement === canvas) {
363:       lookBy(e.movementX || 0, e.movementY || 0);
364:       return;
365:     }
366:     if (!dragging) return;
367:     lookBy(e.clientX - lastX, e.clientY - lastY);
368:     lastX = e.clientX; lastY = e.clientY;
369:   });
370: 
371:   canvas.addEventListener('pointermove', e => {
372:     if (e.pointerType !== 'touch' || !dragging) return;
373:     lookBy(e.clientX - lastX, e.clientY - lastY);
374:     lastX = e.clientX; lastY = e.clientY;
375:   });
376: 
377:   canvas.addEventListener('wheel', e => {
378:     if (!G.running || player.firstPerson) return;
379:     e.preventDefault();
380:     player.camDist = clamp(player.camDist + Math.sign(e.deltaY) * 0.55, 2.8, 10.5);
381:   }, { passive: false });
382: 
383:   document.addEventListener('pointerlockchange', () => {
384:     if (document.pointerLockElement !== canvas && player && player.firstPerson) {
385:       // keep first-person, but let the cursor breathe until the next click
386:       G.keys = G.keys || {};
387:     }
388:   });
389: }
