391: function lookBy(dx, dy) {
392:   if (!player) return;
393:   if (player.firstPerson) {
394:     player.viewYaw += dx * 0.0026;
395:     player.viewPitch = clamp(player.viewPitch - dy * 0.0022, -1.15, 1.15);
396:     player.facing = player.viewYaw;
397:     player.lastDrag = G.time;
398:   } else {
399:     player.camAngle -= dx * 0.005;
400:     player.camPitch = clamp(player.camPitch + dy * 0.0034, -0.16, 0.95);
401:     player.lastDrag = G.time;
402:   }
403: }
404: 
405: function ensurePointerLockIfFirstPerson() {
406:   const canvas = renderer && renderer.domElement;
407:   if (!canvas || !player || !player.firstPerson) return;
408:   if (document.pointerLockElement === canvas) return;
409:   try { canvas.requestPointerLock && canvas.requestPointerLock(); } catch (_) { /* noop */ }
410: }
