412: /* ------------------------------------------------------------------ */
413: /*  Interaction                                                       */
414: /* ------------------------------------------------------------------ */
415: function findInteractable() {
416:   if (!G.running || G.over || !player || player.dead) return null;
417:   const p = player.pos;
418:   const candidates = [];
419: 
420:   for (const npc of world.npcList) {
421:     const d = Math.hypot(npc.pos.x - p.x, npc.pos.z - p.z);
422:     if (d < 3.1) candidates.push({ d, label: npc.interactLabel, run: () => npc.interact() });
423:   }
424: 
425:   for (const pickup of world.pickups) {
426:     if (!pickup.active) continue;
427:     const d = Math.hypot(pickup.pos.x - p.x, pickup.pos.z - p.z);
428:     if (d < 2.7) candidates.push({ d, label: pickup.interactLabel, run: () => pickup.interact() });
429:   }
430: 
431:   for (const id in world.altars) {
432:     const a = world.altars[id];
433:     const d = Math.hypot(a.x - p.x, a.z - p.z);
434:     if (d < 4.3 && !a.active) {
435:       candidates.push({ d, label: `Despertar ${a.name}`, run: () => world.activateAltar(id) });
436:     }
437:   }
438: 
439:   if (!candidates.length) return null;
440:   candidates.sort((a, b) => a.d - b.d);
441:   return candidates[0];
442: }
443: 
444: function updateInteractions() {
445:   if (!G.running || G.over || ui.modalOpen || player.dead) {
446:     currentInteract = null;
447:     ui.showInteract(null);
448:     return;
449:   }
450:   currentInteract = findInteractable();
451:   ui.showInteract(currentInteract ? currentInteract.label : null);
452: }
453: 
454: function interact() {
455:   if (ui.modalOpen || !currentInteract) return;
456:   const action = currentInteract.run;
457:   G.keys = {};
458:   action();
459:   currentInteract = null;
460: }
