462: /* ------------------------------------------------------------------ */
463: /*  Mobile controls                                                   */
464: /* ------------------------------------------------------------------ */
465: function setupMobile() {
466:   if (!isTouch) return;
467:   const stick = $('stick');
468:   const knob = $('stickKnob');
469:   if (stick && knob) {
470:     let id = null;
471:     const max = 44;
472:     const setStick = (x, y, rect) => {
473:       let dx = x - (rect.left + rect.width / 2);
474:       let dy = y - (rect.top + rect.height / 2);
475:       const len = Math.hypot(dx, dy);
476:       if (len > max) { dx = dx / len * max; dy = dy / len * max; }
477:       knob.style.transform = `translate(${dx}px,${dy}px)`;
478:       player.joystick = new THREE.Vector3(dx / max, -dy / max, 0);
479:     };
480:     stick.addEventListener('pointerdown', e => {
481:       e.preventDefault();
482:       id = e.pointerId;
483:       stick.setPointerCapture(id);
484:       setStick(e.clientX, e.clientY, stick.getBoundingClientRect());
485:     });
486:     stick.addEventListener('pointermove', e => {
487:       if (e.pointerId !== id) return;
488:       e.preventDefault();
489:       setStick(e.clientX, e.clientY, stick.getBoundingClientRect());
490:     });
491:     const release = e => {
492:       if (id !== null && e.pointerId !== id) return;
493:       id = null;
494:       knob.style.transform = '';
495:       player.joystick = new THREE.Vector3();
496:     };
497:     stick.addEventListener('pointerup', release);
498:     stick.addEventListener('pointercancel', release);
499:   }
500: 
501:   document.querySelectorAll('.mbtn').forEach(btn => {
502:     const m = btn.dataset.m;
503:     let held = false;
504:     btn.addEventListener('pointerdown', e => {
505:       e.preventDefault();
506:       if (!G.running || ui.modalOpen || G.over) return;
507:       held = true;
508:       if (m === 'attack') player.pressAttack();
509:       else if (m === 'fire') player.magicDown('fire');
510:       else if (m === 'bolt') player.magicDown('bolt');
511:       else if (m === 'ice') player.magicDown('ice');
512:       else if (m === 'dodge') player.dodge();
513:       else if (m === 'interact') interact();
514:       else if (m === 'heal') player.usePotion();
515:     });
516:     const up = e => {
517:       e.preventDefault();
518:       if (!held) return;
519:       held = false;
520:       if (m === 'attack') player.releaseAttack();
521:       else if (m === 'fire') player.magicUp('fire');
522:     };
523:     btn.addEventListener('pointerup', up);
524:     btn.addEventListener('pointercancel', up);
525:     btn.addEventListener('pointerleave', up);
526:   });
527: }
