529: /* ------------------------------------------------------------------ */
530: /*  Extra wiring                                                      */
531: /* ------------------------------------------------------------------ */
532: function bindGameplayExtras() {
533:   // pause automatically when the tab loses focus
534:   document.addEventListener('visibilitychange', () => {
535:     if (document.hidden && G.running && !G.over) {
536:       ui.openPause();
537:       G.paused = true;
538:     }
539:   });
540: 
541:   // first-person crosshair follows the mode even if set elsewhere
542:   if (player) ui.setCrosshair(!!player.firstPerson);
543: 
544:   // debug handle for automated visual checks
545:   window.__aetheria = {
546:     G, ui, world, player, quests, effects, audio, camera, renderer, scene,
547:     start: startGame,
548:     teleport(x, z) { player.group.position.set(x, heightAt(x, z), z); player.updateCamera(0.016, true); },
549:     victory: () => handleBossDefeated(),
550:   };
551: }
552: 
553: /* ------------------------------------------------------------------ */
554: /*  Main loop                                                         */
555: /* ------------------------------------------------------------------ */
556: function animate() {
557:   requestAnimationFrame(animate);
558:   if (!renderer || !scene || !camera) return;
559: 
560:   const dt = Math.min(G.clock ? G.clock.getDelta() : 0.016, 0.05);
561: 
562:   if (!G.running) {
563:     // title-screen camera: slow, cinematic orbit over the village
564:     menuT += dt;
565:     G.time += dt;
566:     if (world) world.update(dt);
567:     if (effects) effects.update(dt);
568:     const cx = 6 + Math.sin(menuT * 0.075) * 24;
569:     const cz = 28 + Math.cos(menuT * 0.075) * 24;
570:     const cy = heightAt(cx, cz) + 12;
571:     camera.position.lerp(new THREE.Vector3(cx, cy, cz), 1 - Math.exp(-dt * 1.4));
572:     camera.lookAt(6, heightAt(6, 28) + 4.2, 28);
573:     camera.fov += ((61 - camera.fov) * (1 - Math.exp(-dt * 2)));
574:     camera.updateProjectionMatrix();
575:     updateSunTarget();
576:     renderer.render(scene, camera);
577:     return;
578:   }
579: 
580:   const modal = ui.modalOpen || G.over;
581:   G.paused = !!modal || !G.running;
582: 
583:   if (!G.paused) {
584:     G.time += dt;
585:     const frozen = (G.hitStop || 0) > 0;
586:     if (frozen) G.hitStop = Math.max(0, G.hitStop - dt);
587:     const step = frozen ? dt * 0.16 : dt;
588: 
589:     player.update(step);
590:     player.tickPending(step);
591:     world.update(step);
592: 
593:     const list = G.enemies;
594:     for (let i = 0; i < list.length; i++) list[i].update(step);
595: 
596:     effects.update(step);
597:     updateInteractions();
598:     updateSunTarget();
599: 
600:     if (G.time - lastHudPulse > 0.05) {
601:       lastHudPulse = G.time;
602:       ui.update(dt);
603:     }
604:     updateProximityAudio();
605:     audio.update(dt);
606:   } else if (G.over) {
607:     if (world) world.update(dt * 0.4);
608:     if (effects) effects.update(dt * 0.4);
609:   }
610: 
611:   renderer.render(scene, camera);
612: }
613: 
614: function updateProximityAudio() {
615:   if (!audio || !audio.ready || !player) return;
616:   const p = player.pos;
617:   const river = Math.abs(p.x - riverX(p.z));
618:   const lake = Math.hypot(p.x - 58, p.z + 72);
619:   const water = clamp(1 - Math.min(river, lake) / 26, 0, 1);
620:   let fire = 0;
621:   for (const f of world.fireLights) {
622:     const d = Math.hypot(p.x - f.light.position.x, p.z - f.light.position.z);
623:     fire = Math.max(fire, clamp(1 - d / 15, 0, 1));
624:   }
625:   audio.setProximity({ water, fire, combat: 0 });
626: }
627: 
628: /* ------------------------------------------------------------------ */
629: /*  Go                                                                */
630: /* ------------------------------------------------------------------ */
631: boot();

