const mountains = new THREE.Group();
const rockMat = new THREE.MeshLambertMaterial({ color: 0x5d6785 });
const snowMat = new THREE.MeshLambertMaterial({ color: 0xd7c9d8 });
for (let i = 0; i < 26; i++) {
