    x.strokeStyle = '#241d30'; x.lineWidth = 5.5;
    x.beginPath(); x.ellipse(0, -1, 28, 32, 0, Math.PI * 1.02, Math.PI * 1.98); x.stroke();
    x.lineWidth = 2.2;
    x.beginPath(); x.ellipse(0, -1, 27, 31, 0, Math.PI * .08, Math.PI * .92); x.stroke();
