/** Painterly stone texture for roads / plazas. */
export function makeStoneTexture() {
  const [c, x] = canvas(256, 256);
  const rnd = mulberry32(11);
  x.fillStyle = '#bc9f72'; x.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 900; i++) {
    x.globalAlpha = 0.08 + rnd() * 0.2;
    x.fillStyle = ['#d2b78d', '#a88962', '#c7aa7d', '#94795a', '#e0c9a1'][(rnd() * 5) | 0];
    x.beginPath(); x.ellipse(rnd() * 256, rnd() * 256, 2 + rnd() * 12, 1 + rnd() * 5, rnd() * 3, 0, 7); x.fill();
  }
  x.globalAlpha = .22; x.strokeStyle = '#7c6448'; x.lineWidth = 1.2;
  for (let i = 0; i < 70; i++) {
    const px = rnd() * 256, py = rnd() * 256;
    x.beginPath(); x.moveTo(px, py); x.lineTo(px + 10 + rnd() * 20, py + (rnd() - .5) * 8); x.stroke();
  }
  return tex(c, { repeat: [1, 1] });
}

